programs.sol:
"""Sparse spelling-based approximation of a multilingual pre-/advance signal.

Positive rules recognize advance markers, their compounds, preview, preset,
and prefetch. Related yu-reading characters and doubt/expectation phrases
have separate rules. Negative rules cover certain word-internal continuations
after d in Russian and Czech, plus preclude/preflight and expedite.
Only the preceding token and a four-byte tail are remembered; documents reset
both. Coefficients are approximate values measured on training text.
"""
import re
from functools import lru_cache
from opencc import OpenCC

READS = ()
SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=16384)
def simplify(text):
    return text if text.isascii() else SIMPLIFY.convert(text)


def advance_signal(text):
    word = text.strip()
    if word == '预':
        return 9.9
    if word == '予':
        return 5.0
    if word == '裕':
        return 5.7
    if word == '欲':
        return 1.1
    if word == '예':
        return 4.0
    if word == 'dự':
        return 9.8
    if word.startswith('预'):
        suffix = word[1:]
        if suffix in ('期', '计', '先', '留', '售', '算', '订'):
            return 4.5
        if suffix in ('防', '备', '告'):
            return 2.3
        if suffix in ('警', '报'):
            return 0.0
        return 0.9
    lower = word.lower()
    if lower == 'preview':
        return 4.7 if text[:1].isspace() else 2.5
    if re.fullmatch(r'pre(?:defined|determined|set|fetch|load|paid|order)', lower):
        return 1.2
    return 0.0


# Completions of the advance-marker compounds: expectation, scheduling,
# announcements, budgets, reservations, prevention, and forecasts.
HAN_COMPLETIONS = {
    '期': 8.9, '定': 7.1, '计': 6.4, '算': 6.2,
    '告': 8.0, '估': 4.2, '后': 5.2, '付费': 5.1,
    '约': 3.6, '订': 3.5, '装': 3.9,
    '想': 3.8, '防': 2.8, '备': 2.2, '习': 2.8,
    '测': 2.0, '感': 2.0,
}
YE_COMPLETIONS = {
    '정': 8.4, '비': 5.9, '절': 4.6, '총': 1.9,
    '술': 1.9, '제': 1.2, '주': 1.0, '방': 1.5,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, tail = ('', b'') if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_bytes[-1]
    text = simplify(prefix.token_strings[-1])
    word = text.strip()
    joined = tail + raw
    completed = simplify(joined.decode('utf-8', errors='ignore'))
    value = advance_signal(text)
    # A byte-split character is recognized when it completes. The two-byte
    # prefixes of 预 and 預 already evoke a weaker anticipation signal.
    continuation_byte = bool(raw) and 0x80 <= raw[0] < 0xc0
    if continuation_byte and joined.endswith((b'\xe9\xa2', b'\xe9\xa0')):
        value = 5.5
    elif continuation_byte:
        if completed.endswith('预'):
            value = 9.9
        elif completed.endswith('予'):
            value = 5.0
        elif completed.endswith('裕'):
            value = 5.7
    if previous in ('预', '予'):
        value += HAN_COMPLETIONS.get(word, 0.0)
    elif previous == '예':
        value += YE_COMPLETIONS.get(word, 0.0)
    elif previous == 'dự' and word in ('án', 'phòng'):
        value += 1.2
    elif previous.lower() == 'pre':
        if word.lower() == 'view':
            value += 5.0
        elif word.lower() in ('-order', 'order', '-defined', '-set', '-loaded'):
            value += 2.5
        elif word.lower().startswith(('clud', 'flight')):
            value -= 2.5
    # A second, negative response: Russian d-initial word continuations.
    # Keep pred- separate: it is the Russian advance/prevention prefix.
    old = previous.lower()
    if not text[:1].isspace():
        if old.endswith('д') and not old.endswith('пред'):
            for onset, strength in (
                ('ел', -3.8), ('ум', -3.5), ('ви', -2.1),
                ('лин', -3.5), ('еш', -1.8),
            ):
                if word.startswith(onset):
                    value += strength
                    break
        elif old.endswith('пред'):
            for onset, strength in (('от', 3.5), ('уп', 4.0), ('оп', 2.7)):
                if word.startswith(onset):
                    value += strength
                    break
        elif old.endswith('d') and word.startswith('ě'):
            value -= 2.7
        elif old == 'exp' and word.lower().startswith('edit'):
            value -= 2.1
        # Preset and prefetch, when the tokenizer divides inside the word.
        if old.endswith('p') and word.lower() == 'reset':
            value += 3.8
        elif old.endswith('pref') and word.lower() == 'etch':
            value += 4.0
        if previous.endswith('疑') and word == '虑':
            value += 3.8
        elif previous.endswith('意') and word == '料':
            value += 3.2
    if word == '裕':
        value = 7.5 if previous.endswith('余') else 1.5
    previous = word
    if continuation_byte and completed:
        previous = completed[-1]
    return (doc, previous, joined[-4:]), value

"""An orthographic cam detector, with nearby spelling contrasts.

The strongest positive response is to the short stem 'cam', including
c + am split over tokens. Completed camera words respond more mildly.
'In case' and several cas-/cap- spellings give negative responses.
Some ka-m/ka-n spellings in other scripts receive similar positive values.
Repeated middle dots have a separate small negative response.
These are spelling rules, not a general detector of cameras or conditions.
"""
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=100000)
def response(s, previous):
    word = s.strip().lstrip('._/\\')
    low = word.lower()
    prev = previous.strip().lower()
    if low == 'cam':
        if not s[:1].isspace():
            return 9.0 if previous[-1:].isalpha() else 6.0
        return 5.3 if word[0].isupper() else 4.1
    if 'camera' in low:
        return 2.1
    if low.endswith('webcam'):
        return 6.5 if word[:1].isupper() else 3.5
    if low == 'kam':
        return 1.7
    if low == 'cass':
        return 2.5
    if low in ('case', 'cases'):
        if prev == 'in' and word == 'case':
            return -5.3
        if prev == 'special':
            return -2.4 if low == 'case' else -1.8
        return -0.1 if low == 'case' else 0.0
    if low in ('cas', 'casa', 'caso', 'casing'):
        if prev in ('in', 'en', 'nel', 'nell', 'delle', 'il', 'la',
                    'di', 'nella', 'della', 'dalle', 'da'):
            return {'cas': -3.2, 'casa': -1.5,
                    'caso': -5.5, 'casing': -1.7}[low]
        return {'cas': -0.6, 'casa': -1.4,
                'caso': -1.7, 'casing': -1.7}[low]
    if low == 'cape':
        return -1.2
    if low == 'cu' and prev in ('il', 'nel', 'di', 'mio', 'suo'):
        return -3.2
    if not s[:1].isspace() and prev.endswith('c'):
        if low == 'am':
            return 7.0
        if low.startswith('am'):
            return 0.7
        if low == 'ass':
            return 4.0
        if low.startswith('ass'):
            return 1.2
        if low.startswith(('asa', 'aso', 'ased')):
            return -4.5
        if low.startswith(('ase', 'asi')):
            return -1.5
        if low.startswith('ug'):
            return -4.5
        if low == 'ag':
            return -2.3
    if not s[:1].isspace() and prev.endswith('k') and low == 'am':
        return 3.5
    # Related syllables written in other alphabets, or Japanese kana.
    if any(ord(ch) > 127 and ch.isalpha() for ch in s + previous):
        a, b = anyascii(previous).strip().lower(), anyascii(s).strip().lower()
        if previous.endswith(('ك', 'ک')) and s.startswith('ام'):
            return 5.0
        if a.endswith(('c', 'k')) and b == 'am':
            return 2.0
        if a.endswith(('ca', 'ka')) and b == 'm':
            return 3.0
        if previous.endswith(('か', 'カ')):
            if s.startswith(('ん', 'ン', 'め', 'メ', 'ま', 'マ')):
                return 4.0
            if s.startswith('ッ'):
                return 1.6
    if low == '··':
        return -0.82
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    return (doc, s), response(s, previous)

"""A partial local technical-compound detector.

Resource use, power management, control interfaces and computing names
usually give positive predictions. Device nouns after descriptive words
are negative. Only the preceding token fragment is needed. Document-opening
function words and Markdown headings have separate fixed responses.
Many unrelated and weak responses are deliberately left at zero.
"""
import re

READS = ()

FUNCTION_WORDS = set(
    'a an the this that these those such same another any each every some other '
    'all their his her my our your its which what of and or for with to in as per '
    'first second third one two three four five six seven eight nine ten'.split()
)
POWER_TERMS = set(
    'supply supplies distribution analysis play plays plan configuration '
    'state states failure requirements saving savings'.split()
)
# Completions of recognizable computing names, not token IDs.
COMPUTING_NAMES = {
    'acpi': 4.8,       # power-management interface
    'pcre': 5.0,       # regular-expression library
    'phpunit': 2.5,
    'phpstan': 0.7,
    'pkg_resources': 1.3,
    'cmark': 3.3,      # Markdown parser
    'cgroup': 3.1,     # resource-control groups
    'cgroups': 2.8,
    'psutil': 3.3,     # process/resource monitoring
    'lru': 1.7,        # cache replacement policy
    'pcap': 3.2,       # packet capture
    'mapstructure': 2.5,
}
OPENING_WORDS = {
    'The': -0.5, 'A': 0.45, 'To': 1.17,
    'On': -0.54, 'Is': -1.17, 'Not': -1.23,
}


def response(token, previous):
    word = token.strip().lower()
    match = re.search(r'([A-Za-z]+)$', previous)
    prev = (match.group(1) if match else previous.strip()).lower()

    # Chinese resource and control compounds.
    if word in {'耗', '消耗'} and prev in {'功', '能', '能源', '能量'}:
        return 5.3
    if prev == '能' and word == '效':
        return 4.2
    if prev == '计算' and word == '资源':
        return 2.7
    if prev == '控制' and word in {'流', '室'}:
        return 3.8

    if word in {'consumption', 'usage'}:
        if prev in {'power', 'energy', 'resource', 'memory'}:
            if word == 'usage' or prev in {'resource', 'memory'}:
                return 3.9
            return 4.9
        if word == 'usage' and prev in {'data', 'cpu'}:
            return 3.4
        if prev in {'fuel', 'water', 'oxygen', 'gas', 'computer', 'disk', 'internet'}:
            return 1.7
        return -0.3
    if prev == 'power':
        if word == 'management':
            return 4.3
        if word == '-play':
            return 4.1
        if word in POWER_TERMS or word in {'plant', 'plants', 'use'}:
            return 3.0
        if word in {'source', 'sources', 'plane', 'planes', 'allocation', 'house'}:
            return 2.3
    if prev == 'energy':
        if word in {'use', 'production'}:
            return 3.4
        if word.startswith('-eff'):
            return 4.2 if word == '-efficient' else 2.6
        if word == 'efficiency':
            return 2.9
        if word in {'efficient', '-saving', 'saving', 'savings', 'expenditure'}:
            return 2.0
    if prev == 'control':
        if word == 'unit':
            return 4.4
        if word in {'panel', 'panels', 'room'}:
            return 4.0
        if word in {'center', 'centre'}:
            return 3.1
        if word in {'flow', '-flow', 'board', 'characters', 'units'}:
            return 2.6
    if prev in {'computing', 'computational', 'processing', 'system'}:
        if word in {'power', 'resource', 'resources'}:
            return 3.1
        if word in {'unit', 'units'}:
            return 3.5
    if word in {'structure', 'structures'} and prev in {'data', 'metadata'}:
        return 1.25 if token[:1].isspace() or prev == 'metadata' else 2.8

    if word in {'device', 'devices', 'machine', 'machines', 'appliances', '设备'}:
        if prev in {'memory', 'storage', 'communication', 'communications', 'power'}:
            return -2.3 if prev == 'memory' else -1.8
        if prev in FUNCTION_WORDS or not prev.isalpha():
            return 0.1
        return -0.9 if word in {'devices', 'appliances'} else -0.65

    joined = prev + word
    if joined in {'cpus', 'cput'}:  # plural CPUs and CPU-time/type identifiers
        return 6.8
    if joined == 'cpu':
        return 2.8
    if joined == 'cpuf':  # beginning of cpufeatures
        return 4.5
    if joined in COMPUTING_NAMES:
        return COMPUTING_NAMES[joined]
    if (word in {'unit', 'units'} and token[:1].isspace()
            and prev.isalpha() and prev not in FUNCTION_WORDS):
        return 0.9
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    if previous in {'', '<|endoftext|>'} and token in OPENING_WORDS:
        value = OPENING_WORDS[token]
    elif previous in {'', '<|endoftext|>'} and token in {'#', '##'}:
        value = 0.6
    else:
        value = response(token, previous)
    return (doc, token), value

"""A boundary-sensitive approximation, dominated by the assistant role label.

Assistant headers spike positively, especially after tool output. Chat-control
markers, `else`, and two code-boundary patterns have fixed responses. Sentence-ending punctuation
is more negative after a mixture of exclamations and ellipses, or immediately
after an unfinished function word.
A coarse case/digit rule handles the offset at the start of a document.
These rules leave most of the component's small, word-specific variation out.
"""
READS = ()

# Words which usually require something else before a sentence can end.
UNFINISHED = set(
    'a an the this that these those of to in on at for from '
    'with by as and or but if than is are was were be been being'.split()
)
CHAT_MARKERS = {
    '<tool_call>': 0.064,
    '<think>': 0.028,
    '</think>': -0.043,
    '<|endoftext|>': -0.026,
}
# Dotted pauses and combinations of sentence-ending punctuation.
DOTTED_ENDINGS = {'...', '..', '....', ',...', ',.', '.!', ',!'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, tool, bangs, dots = '', False, 0, 0
    else:
        _, previous, tool, bangs, dots = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    mixed = min(15, bangs, dots)
    unfinished = previous.strip().lower() in UNFINISHED
    value = -0.001

    if token == 'assistant' and previous == '<|im_start|>':
        value = 0.866 + 0.098 * tool
    elif token in CHAT_MARKERS:
        value = CHAT_MARKERS[token]
    elif word == 'else':
        value = -0.145
    elif word == '});':
        value = -0.125
    elif word.startswith('#!'):
        value = -0.40
    elif token == '!':
        value = 0.030 - 0.126 * mixed - 0.301 * unfinished
    elif token == '.':
        value = -0.003 - 0.043 * mixed - 0.008 * unfinished
    elif token in DOTTED_ENDINGS:
        value = 0.033 - 0.116 * mixed - 0.117 * unfinished

    bangs += token == '!'
    dots += token in DOTTED_ENDINGS
    value = max(-1.3, value)

    if first and not token.startswith('<'):
        value -= 0.05
        if word.isalpha():
            if word.islower() or not word.isascii():
                value -= 0.095
            elif word.istitle():
                value -= 0.025
        elif word.isdigit():
            value += 0.14
    tool = tool or token == '</tool_response>'
    return (doc, token, tool, bangs, dots), value

"""Approximate a quotation / string-delimiter response.

Escaped quotes, opening quotation marks, and shell here-document delimiters
get positive values. Contractions and closing punctuation are mostly quiet.
Spaced quotes depend on nearby string syntax and quote repetition.
Closing marks can respond again after a long gap without quotation marks.
Only a short text tail and the distance from the last quote are remembered.
"""
import re
import unicodedata

READS = ()
HEREDOC = re.compile(r'<{2,3}-?\s*[\'\"]?$')


def quoted_value(s, prev, age, tail, places):
    i = places[0]
    q, before, after = s[i], s[:i], s[i + 1:]
    if HEREDOC.search(tail + before):
        return 1.20
    if q == '`':
        return -0.07
    if q in '“‘':
        return 0.42
    if q in '«‹':
        return 0.85
    if q in '„‚':
        return 0.68
    if q in '「『':
        return 0.47
    if q in '」』':
        return 0.0
    if q == '″':
        return 1.03
    if q in '”’»›':
        if q == '’' and after and after[0].isalpha():
            return -0.03
        if not before and not after and age >= 32:
            return 0.23 if prev[-1:].isalpha() else 0.70
        return 0.33 if before and (before.isspace() or before[-1] in '!…') else 0.03

    # Backslash-escaped delimiters, including quotes split across tokens.
    if before.endswith('\\') or (not before and prev.endswith('\\')):
        if not after:
            return 1.33 if before[:1].isspace() else 0.90
        return 0.60 if after.startswith('\\') else 0.33
    if q == "'":
        if not before and prev[-1:].isalpha():
            return -0.03
        if not before:
            return 0.15 if after[:1].isalpha() else 0.08 if after else 0.22
        return 0.13

    # Straight double quotes: word onset, closure, or code/string opener.
    if len(places) > 1:
        return 0.28
    if after[:1].isalpha():
        return 0.83
    if not before:
        if after:
            if after[0] == ':':
                return -0.08
            if age >= 32:
                return 0.44
            return 0.21 if after.isspace() else 0.04
        if prev[-1:].isalnum():
            return 0.23 if age >= 32 else 0.0
        return 0.83
    if before.isspace():
        end = prev.rstrip()
        if re.search(r'[\"\'],$', end):
            return -0.11
        if re.search(r'[\"\']:$', end):
            return 0.08
        if end.endswith(('=', '+', '>')):
            return 0.06
        if end and (end[-1] in '.:' or end[-1].isdigit()):
            return 0.32
        return 0.21 if age < 8 else 0.33
    if before.endswith('{'):
        return 0.20 if before[:1].isspace() else 0.52
    if before[-1] in '([':
        return 0.17
    if before[-1] in '=:':
        return 0.30
    return 0.18


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        age, tail, prev, pending = 1000, '', '', False
    else:
        _, age, tail, prev, pending = carry
    s = prefix.token_strings[-1]
    places = [i for i, c in enumerate(s)
              if c in '\"\'`「」『』″' or unicodedata.category(c) in ('Pi', 'Pf')]
    opening_block = s.strip() == 'EOF' and bool(HEREDOC.search(tail))
    if s.strip() == 'EOF':
        value = 2.76 if opening_block else 0.62
    elif pending and '\n' in s:
        value = 1.90 if s.isspace() else 1.10
    else:
        value = quoted_value(s, prev, age, tail, places) if places else 0.0
    carry = (doc, 1 if places else age + 1, (tail + s)[-64:], s, opening_block)
    return carry, value

"""An opening pulse, waiting words, and a few conventional text labels.

Document openings (including initial repetitions) get a positive pulse,
scaled by token form and broad word classes rather than token-ID lookup.
An opening Title: colon is exceptionally strong. Away from the opening,
waiting words and navigation/metadata labels give smaller positive values;
'This is a' and the Java utility namespace give small negative values.
Other positions are zero. These are approximations to observed patterns.
"""
from functools import lru_cache
import regex as re

READS = ()


@lru_cache(maxsize=8192)
def opening(text):
    s = text.strip()
    w = s.lower()
    if not s:
        if '\t' in text:
            return 4.3
        if '\n' in text or '\r' in text:
            return 3.1
        return 5.7 if len(text) > 1 else 2.5
    if s.startswith('<|') and s.endswith('|>'):
        return 4.2
    if s == 'Title':
        return 2.6
    if s.isdecimal():
        return 2.9
    if re.search(r'\p{Script=Han}', s):
        return 1.7
    if not s.isascii():
        return 1.2 if re.fullmatch(r'\p{Punctuation}+', s) else 2.4
    if not any(c.isalpha() for c in s):
        if s in ('.', ',', ';', ':', '!', '?'):
            value = 1.3
        elif any(c in s for c in '()[]{}'):
            value = 2.1
        elif any(c in s for c in '\'"`'):
            value = 3.2
        else:
            value = 2.6
        return value + (0.8 if '\n' in text else 0.)
    if w in ('a', 'an'):
        return 5.6
    if w == 'the':
        return 4.7 if s[0].isupper() else 3.8
    if w in ('no', 'not', 'never', 'neither'):
        return 5.2
    if w in ('import', 'package', 'class', 'def'):
        return 5.8
    if len(s) == 1 and s.isalpha():
        return 4.7 if s.isupper() else 4.1
    value = 3.4 - 0.5 * text[:1].isspace()
    value += 0.5 * s[0].isupper()
    if s.startswith(('_', '.')):
        value += 0.7
    return value


def step(carry, prefix, upstream):
    token = prefix.token_ids[-1]
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[0]:
        position, initial, repeating, tail = 0, text, True, ''
    else:
        _, position, initial, repeating, previous_token, tail = carry
        position += 1
        repeating = repeating and token == previous_token
    tail = (tail + text)[-64:]
    if position == 1 and initial == 'Title' and text == ':':
        value = 15.8
    elif repeating:
        value = opening(initial)
    elif re.search(r'\bwait(?:s|ed|ing|ers?)?\Z', tail, re.I):
        word = re.search(r'\b(wait\w*)\Z', tail, re.I).group(1)
        if word.lower() == 'wait':
            if word.isupper():
                value = 0.9
            else:
                value = 0.84 if text[:1].isspace() else 0.76
        else:
            value = 0.7 if word.lower().endswith('ing') else 0.5
    elif re.search(r'\bView More\Z', tail):
        value = 1.4
    elif re.search(r'\b(?:View (?:Details|Profile)|Learn More)\Z', tail):
        value = 0.7
    elif re.search(r'\bThis is a\Z', tail):
        value = -0.5
    elif tail.endswith('java.util'):
        value = -0.4
    elif tail.endswith('showing results'):
        value = 0.6
    elif tail.endswith('About The Author'):
        value = 1.3
    elif text.strip().lower() in ('worksheet', 'worksheets'):
        value = 1.4 if text[:1].isupper() else 0.4
    else:
        value = 0.
    return (doc, position, initial, repeating, token, tail), value

programs.haiku:
"""Layer-1 MLP down-projection unit 4678: a document-start and middle-dot detector.

What it does, in plain terms:
- First token of each document (or of each row): a large, token-dependent value.
  About 3.4 for a token that starts a word without a leading space (or code-like
  tokens), about 2.4 for a space-prefixed word or non-Latin text, and about 1.7 for CJK
  (Chinese, Japanese, Korean) characters.
- The middle-dot token "··": a fixed value of about 4.6 wherever it occurs.
- The word "Wait" (and its spacing/case variants) mid-document: a small value, about 0.8.
- Everywhere else: 0.

Why: the component is an almost context-free, token-identity signal. It is strong at the
start of a document, where attention has nothing earlier to look at, and on a few
tokens that recur in the data. Its size on a token depends mostly on how the token is
written (script, leading space, code-likeness), which is what the three-level rule uses.
