READS = ()

DOT_PAIR = "··"
WAIT_WORDS = {"Wait", " Wait", " wait", " waiting"}


def is_cjk(text):
    return any(
        0x4E00 <= ord(ch) <= 0x9FFF  # CJK ideographs
        or 0x3040 <= ord(ch) <= 0x30FF  # hiragana and katakana
        or 0xAC00 <= ord(ch) <= 0xD7AF  # hangul
        for ch in text
    )


def doc_start_value(token):
    if is_cjk(token):
        return 1.7
    if token.startswith(" ") or not token.isascii():
        return 2.4
    return 3.4


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == DOT_PAIR:
        return carry, 4.6
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, doc_start_value(token)
    if token in WAIT_WORDS:
        return carry, 0.8
    return carry, 0.0

