"""Source-file header and import-list detector.

Java imports and PHP uses produce large negative values; Rust uses, C#
using directives, and Go imports are weaker. Numbered/escaped snippets are
attenuated. Initial keywords have separate values. A few related line/header
patterns get small responses; otherwise the prediction is zero.
"""
import math
import re

READS = ()
JAVA = re.compile(r'\b(?:package|import)\s+(?:static\s+)?[\w.*]+\s*;')


def response(text, beginning, token, position):
    word = token.strip()
    if word not in {'import', 'use', 'using', 'from', 'namespace', 'at', 'Tags'}:
        return 0.0
    if position == 0:
        return {'import': 4.35, 'using': 0.78, 'from': 1.46}.get(token, 0.0)

    # Recognize line margins, including line-numbered listings and diffs.
    clean = text.replace('\\n', '\n').replace('\\r', '\r')
    line = clean.rsplit('\n', 1)[-1]
    margin = (not line.strip() or bool(re.fullmatch(r'\s*\d+', line))
              or line.strip() in ('+', '-', '|'))
    numbered = token.startswith('\t') and bool(re.search(r'\d\s*$', line))
    scale = 0.45 if numbered else 1.0
    if token.startswith(' ') and word in ('import', 'use'):
        scale *= 0.85 if '@@ ' in clean else 0.4
    if text.endswith('\\n') or text.endswith('\\n\\n'):
        scale *= 0.6

    if word == 'import':
        if JAVA.search(clean):
            if not margin:
                return 0.6
            if beginning.startswith('package '):
                value = -27.5
            elif re.search(r'\bpackage\s+[\w.]+;', clean):
                value = -25.8
            else:
                value = -19.7
                # Files beginning directly with imports build up more slowly.
                if beginning.startswith('import'):
                    scale *= 0.45 + 0.55 * (1 - math.exp(-position / 50))
            if numbered and not re.search(
                    r'\bimport\s+(?:static\s+)?[\w.*]+;', clean):
                scale *= 0.5
            return value * scale
        if margin and re.search(r'\bpackage\s+\w+[^;\n]*\n', clean):
            # Go package clauses have no terminating semicolon.
            value = -7.3
            if beginning.startswith('package '):
                value = -18.4
            elif beginning.startswith('//'):
                value = -13.5
            return value * scale
        if margin and re.search(r'(?:^|\n)[\w.]*;\s*$', clean):
            return -13.0 * scale  # A row beginning partway through a header.
        if margin and re.search(r'```(?:java|dart)\s*\n[^`]*$', clean):
            return -7.1 * scale
        return 0.6 if token == 'import' else 0.0

    if word == 'use' and margin:
        if '<?php' in clean or re.search(r'namespace\s+[\w\\]+;', clean):
            value = -26.2 if beginning.startswith('<?php') else -15.9
        elif re.search(r'\buse\s+[^;\n]*::|\bextern crate\b', clean):
            value = -10.6
        else:
            value = -3.0
        return value * scale
    if word == 'using' and margin:
        if (re.search(r'\busing\s+[\w.]+;', clean)
                or re.search(r'\bnamespace\s+[\w.]*\.[\w.]+\s*\{\s*$', clean)):
            return -10.7 * scale
        if '```csharp' in clean or '```c#' in clean:
            return -4.8 * scale
    if token == 'from' and margin:
        return -0.8
    if token == 'namespace' and margin:
        return -2.2
    if word == 'at' and margin and line.count('\t') <= 1:
        return -7.8 if token.startswith('\t') else -3.1
    if token == ' Tags' and text.endswith('Show'):
        return -1.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, beginning, position = '', '', 0
    else:
        _, text, beginning, position = carry
    token = prefix.token_strings[-1]
    value = response(text, beginning, token, position)
    carry = (doc, (text + token)[-2400:], (beginning + token)[:120],
             position + 1)
