"""Approximate code-definition boundaries and base64-like text.

Negative pulses mark braces after routine/type headers and Python definition
colons, excluding ordinary control-flow blocks. A separate mixed-case/digit
run detector approximates encoded payloads. Document starts get form-based
baselines; a leading Title: has a strong positive colon response. State resets
between documents. Fine-grained lexical variation is deliberately omitted.
"""
import re

READS = ()

CONTROL = re.compile(
    r"\b(?:if|for|foreach|while|switch|catch|with|elif|except|return|new)\b")
TYPE = re.compile(
    r'\b(?:class|struct|enum|interface|trait|namespace|impl)'
    r'(?:<[^;\n{}]*>)?\s+\w+')
FUNCTION = re.compile(r"\b(?:function|func|fn|def)\b")


def source_text(text):
    return text.replace('\\n', '\n').replace('\\t', '\t')


def definition(before):
    """Classify a header, keeping loop conditions distinct from signatures."""
    before = re.sub(r'(?m)^[ \t\xa0]*\d+(?:[ \t\xa0]+|$)', '',
                    before.replace('`', '')).strip()
    statement = re.split(r'[;{}]', before)[-1]
    if TYPE.search(statement) and '=' not in statement and not re.search(
            r'\)\s*->', statement):
        return 'type'
    close = before.rfind(')')
    if close < 0:
        return None
    tail = before[close + 1:]
    if re.search(r"[=;{}\"]", tail.replace('=>', '')) or len(tail) > 140:
        return None
    # Find the opening parenthesis of the last balanced argument list.
    depth = 1
    op = close - 1
    while op >= 0:
        if before[op] == ')':
            depth += 1
        elif before[op] == '(':
            depth -= 1
            if not depth:
                break
        op -= 1
    if op < 0:
        return None
    head = before[:op].rsplit('\n', 1)[-1].strip()
    head = re.split(r'[;{}]', head)[-1].strip()
    head = re.sub(r'^\d+\s+', '', head)
    annotation = re.fullmatch(r'\s*:\s*[?\w\\\[\]<>., |&]+\s*', tail)
    if not annotation and (':' in tail.replace('::', '')
                           or ('\n' in tail and tail.strip())):
        return None
    if CONTROL.search(head) and not FUNCTION.search(head):
        return None
    if '=>' in tail:
        return 'closure'
    if re.search(r'\bdef\s+\w+$', head):
        return 'python'
    if FUNCTION.search(head):
        if re.search(r'\bfunction\s*$', head) and not re.search(r'[:=]', head):
            return 'closure'
        return 'function'
    if head.endswith(')') or head.endswith('->'):
        return definition(before[:op])
    # A method name, optionally preceded by its return type and modifiers.
    if re.fullmatch(r'[\w:<>,*&\[\]?~]+(?:\s+[\w:<>,*&\[\]?~]+)*', head):
        return 'function'
    return None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    recent = '' if first else carry[1]
    run = '' if first else carry[2]
    value = 0.0
    if first:
        value = -0.28
        if token.isspace():
            value = -0.44
        elif token.isdigit():
            value = -0.13
        elif token.startswith('<|'):
            value = -0.1
        if token == '<|endoftext|>':
            value = -2.54
        if token.strip() in {'package', 'using', '#include', '/*', '"""'}:
            value = -1.2
    text = token.replace('`', '')
    if re.fullmatch(r'[\s`()]*\{(?:[\r\n\\]*)', text):
        before = source_text(recent + text.split('{', 1)[0])
        kind = definition(before)
        value = {'type': -0.78, 'function': -0.97,
                 'closure': -0.33}.get(kind, value)
        if kind == 'function' and text.lstrip().startswith((')', '(')):
            value *= 0.55
    if ':' in text and ('\n' in text or text.endswith(('\\', ':'))):
        before = source_text(recent + text.split(':', 1)[0])
        if definition(before) == 'python':
            value = -0.74
        elif re.search(r'(?:^|\n)\s*class\s+\w+[^:\n]*$', before):
            value = -0.6
    # A document-initial title label has a distinctive colon response.
    if not first and recent == 'Title' and token == ':':
        value = 7.99
    # A long mixed-case/digit run is usually an encoded binary payload.
    if re.fullmatch(r'[A-Za-z0-9+/]+', token):
        run = (run + token)[-512:]
        if (len(run) >= 24 and any(c.isdigit() for c in run)
                and any(c.isupper() for c in run)
                and any(c.islower() for c in run)):
            value = -0.44
    else:
        tail = re.search(r'[A-Za-z0-9+/]+$', token)
        run = tail.group() if tail else ''
    return (doc, (recent + text)[-1000:], run), value

