"""Ordinal-number detector (negative), for layers.1.mlp.down_proj:4684.

The component turns negative on ordinal numbers ("first", "second", "third", ... and
their translations, and "19th"-style suffixes) and is near zero elsewhere. The size of
the dip depends on the words just before: "the first" is strongest, "a second" weak, and
the time unit in "per second" is the opposite sign.
"""

READS = ()

ENGLISH = {
    "first": -1.7, "second": -1.1, "third": -1.2, "fourth": -1.0, "fifth": -1.2,
    "sixth": -1.5, "seventh": -0.9, "eighth": -1.5, "ninth": -1.2, "tenth": -1.0,
}
# Ordinals in other languages (Spanish, French, Portuguese, German, Chinese, ...)
FOREIGN = {
    "premier": -3.3, "première": -4.5, "premiere": -3.5, "primer": -0.5, "primo": -5.0,
    "prima": -4.0, "primeiro": -5.0, "primeira": -4.5, "primera": -3.3, "deuxième": -2.5,
    "secondo": -3.0, "segundo": -3.0, "segunda": -3.0, "erste": -4.5, "ersten": -4.4,
    "erster": -4.0, "erstes": -4.0, "zweite": -2.5, "zweiten": -2.5, "dritte": -4.0,
    "dritten": -4.0, "第一": -0.8, "第二": -0.6, "第三": -0.6, "º": -4.3,
}
# Words that sit near ordinals in meaning ("last", "next", "the other") respond weakly
WEAK = {"last": -0.5, "next": -0.5, "other": -0.2, "回": -0.8, "회": -0.8, "代": -0.9}
# Suffix pieces that finish an ordinal after a number: "19th", "2nd", "3rd", "1st"
SUFFIX = {"th": -2.0, "st": -3.5, "nd": -2.4, "rd": -2.6}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    before = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if word == "second" and before == "per":
        return carry, 1.3  # "per second": the time unit, which pushes the other way
    if word in ENGLISH:
        scale = 1.6 if before == "the" else 0.4 if before == "a" else 1.0
        return carry, float(ENGLISH[word] * scale)
    if word in FOREIGN:
        return carry, float(FOREIGN[word])
    if word in WEAK:
        return carry, float(WEAK[word])
    if word in SUFFIX and before[-1:].isdigit():
        return carry, float(SUFFIX[word])
    return carry, 0.0

