    """Strength of the vowel fragment immediately following an f sound."""
    # Long suffix chunks are not treated as isolated short syllables.
    if len(s) > 5:
        return 0.3
    if s.startswith('ar'):
        if s == 'ar':
            return 9.0
        if s in ('arr', 'aring'):
            return 8.5
        if s.startswith('are') or s == 'ars':
            return 6.8
        return 4.8
    if s.startswith('an'):
        return 0.2 if s.startswith(('ant', 'and')) else -1.5
    if s.startswith('ah'):
        return 4.1 if s == 'ah' else 2.4
    if s == 'a':
        return 3.3
    if s.startswith('at'):
        return 4.2 if s in ('att', 'ats') else (3.3 if s == 'at' else 1.9)
    if s.startswith('as'):
        return 2.8
    if s.startswith('a'):
        if s.startswith(('ac', 'all', 'alse', 'able')):
            return 0.1
        return 2.2 if len(s) <= 2 else 1.0
    if s.startswith(('eng', 'ern')):
        return -1.9
    if s in ('n', 'nd', 'nt', 'mt'):
        return -0.9
    if s.startswith('err'):
        return 1.1
    return 0.0


