    elif word in ('farm', 'farms', 'farming'):
        value = 2.6
    elif word in ('farmer', 'farmers', 'farther'):
        value = 1.3
    elif word in ('fat', 'fats'):
        value = 1.2 if new_word else 2.8
    elif word in ('fart', 'fasting'):
        value = 2.4
    elif word in ('fair', 'fairly'):
        value = 0.5
    elif word == 'fast':
        value = 3.0 if bare.isupper() else 1.1
        if previous in ('so', 'how', 'as', 'too', 'very'):
