READS = ()
NONE_PREV = {"how", "so", "thus"}
WEAK_PREV = {"as", "too", "very", "most", "this", "that"}
FA_WORDS = {"fa": 1.4, "fat": 1.3, "fast": 1.2, "fam": 1.4, "fas": 1.1, "fax": 0.8, "fal": 0.8, "fair": 0.6}

