    raw = prefix.token_strings[-1]
    prev_word = carry or ""
    starts_word = raw[:1] == " " or not prev_word
    letters = ""
    for ch in raw.strip().lower():
        if not ch.isalpha():
            break
        letters += ch
    base = "" if starts_word else prev_word
    word = base + letters
    ends_word = len(letters) < len(raw.strip()) or raw.strip() == ""
    new_carry = None if ends_word else word
    prev_tok = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    value = 0.0
    if "far" not in base and (word == "far" or (base.endswith("f") and letters.startswith("ar"))):
        # 'far' itself, or the 'ar' that completes an f-fragment: graded by the preceding word
        if prev_tok in NONE_PREV:
            value = 0.0
        elif prev_tok in WEAK_PREV:
            value = 2.0
        else:
            value = 6.0
    elif "far" not in base and word.startswith("far"):
        value = 2.5
