"""Recognize options and operations after short command/code prefixes.

Shell option letters get a positive response, especially near a utility name;
so do subcommands and selected conventional C/PHP identifier continuations.
POSIX constant names come from standard-library tables, not learned token IDs.
The numbers are coarse response levels for these named patterns. Most other
text stays near zero, with negative offsets for document starts, initial
carriage returns, and double-middle-dot separators. This is a suffix-pattern
approximation, not a full shell or programming-language parser.
"""
import errno
import os
import re
import socket
import stat

READS = ()

SHELL_TOOLS = set('''
cat grep egrep fgrep rg ls rm cp mv find sed awk head tail cut sort uniq wc
xargs tee chmod chown mkdir rmdir ln tar unzip zip curl wget ssh ssh-keygen
ssh-keyscan rsync python python3 pip pip3 pytest node npm npx pnpm yarn tsc
git go cargo rustc gcc g++ cc clang javac java mvn make cmake install
pacman apt apt-get dpkg ffmpeg bash sh du df ps kill echo diff patch timeout
'''.split())
COMMAND_VERBS = set('''
run test build install uninstall update add remove status diff checkout
restore reset clone show log commit push pull fetch init tag stash rev ls
clean check fmt fix doc lint start publish list config i
'''.split())
# Names of constants exposed by the POSIX-related standard-library modules.
POSIX_NAMES = {name for module in (os, socket, stat, errno)
               for name in dir(module) if name.isupper() and name[0].isalpha()}
POSIX_PREFIXES = {name[:n] for name in POSIX_NAMES
                  for n in range(2, len(name) + 1)}
SUPERGLOBALS = set('''
GET POST COOKIE REQUEST SESSION SERVER FILES ENV GLOBALS
'''.split())


def predict(s, text):
    if s == '··':
        return -1.98
    if s == '\r' and not text.strip('\r'):
        return -4.18
    if not text:
        return -0.34 if s.isascii() and s.isalpha() else -0.21
    if s == 'cd':
        return 0.61
    if s.startswith(' ') and s.strip() in COMMAND_VERBS:
        match = re.search(r'[a-z][a-z0-9-]*$', text)
        command = match[0] if match else ''
        if command in {'npm', 'pnpm', 'pip', 'pip3'}:
            return 2.25
        if command == 'cargo':
            return 1.95
        if command in {'git', 'go', 'yarn', 'apt', 'apt-get', 'docker'}:
            return 1.5

