        marker = True
        letters = s[1:]
    if marker and re.fullmatch('[A-Za-z]+', letters):
        words = re.findall(r'[A-Za-z][A-Za-z0-9+-]*', text[-100:])
        shell = any(word in SHELL_TOOLS for word in words[-8:])
        long_option = text.endswith('--')
        if long_option:
            return 0.8 if shell else 0.6
        if shell:
            return (1.95 if letters.isupper() else
                    1.58 if len(letters) == 1 else 1.3)
        return 0.2

    stem_match = re.search(r'[A-Za-z_][A-Za-z0-9_]*$', text)
    stem = stem_match[0] if stem_match else ''
