            return 6.0
        if stem in {'st', 'sockaddr', 'va'}:
            return 4.2
        if stem == 'c' and s == '_str':
            return 1.9
        if stem == 'm':
            return 0.8
        if stem and stem + s in POSIX_PREFIXES:
            return 3.0
        if stem in {'GL', 'CL', 'FT'}:
            return 2.3
        if stem == 'cl':
            return 1.2
        if stem == 'in' and s == '_array':
            return 5.1
        if stem == 'is' and s in {'_array', '_string', '_int', '_object',
