        return -0.06
    return -0.001


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        text = ''
    else:
        _, text = carry
    s = prefix.token_strings[-1]
    value = predict(s, text)
    return (document, (text + s)[-120:]), value

programs.haiku:
"""Command-line option detector (v6): short single-dash flags and --long options, fitted scales."""
READS = ()

TOOLS = {"npm", "yarn", "pnpm", "npx", "cargo", "git", "go", "python", "python3", "pip", "docker",
         "make", "grep", "sed", "awk", "cat", "ls", "rm", "cp", "mv", "curl", "wget", "tsc", "node",
         "ts-node", "rustc", "gcc", "ffmpeg", "chown", "chmod", "ssh", "ssh-keygen", "pytest", "sudo",
         "apt", "brew", "gem", "bundle", "kubectl", "tar", "find", "sort", "head", "tail", "diff"}
SUBCOMMANDS = {"run", "test", "build", "add", "install", "status", "diff", "show", "clean", "update",
               "checkout", "commit", "push", "pull", "restore", "start", "init"}
DOC_START = -0.26
SHORT_FLAG = 1.2
LONG_FLAG = 0.67
SUBCOMMAND = 1.7
CD = 0.65

def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    w = s.strip()
    if carry is None or prefix.document_ids[-1] != carry["doc"]:
        carry = {"doc": prefix.document_ids[-1], "prev": "", "tool_on_line": False}
        return carry_update(carry, s, w), DOC_START
    prev = carry["prev"].strip()
    if prev == "-" and w.isalpha() and len(w) <= 2 and carry["tool_on_line"]:
        value = SHORT_FLAG
    elif prev == "--" and w.isalpha() and carry["tool_on_line"]:
        value = LONG_FLAG
    elif prev in TOOLS and s.startswith(" ") and w in SUBCOMMANDS:
        value = SUBCOMMAND
    elif w == "cd":
        value = CD
    else:
        value = 0.0
    return carry_update(carry, s, w), value

def carry_update(carry, s, w):
    if "\n" in s:
        tool_on_line = False
    else:
        tool_on_line = carry["tool_on_line"] or w in TOOLS
    return {"doc": carry["doc"], "prev": s, "tool_on_line": tool_on_line}

programs.sol:
"""Approximate a multilingual relative-marker response from spelling and context.

Large negatives mark Indonesian 'yang', Arabic relatives, Thai ที่, and
Scandinavian relatives/demonstratives. Recent word frequencies disambiguate
Scandinavian words from foreign word fragments, and Indonesian 'yang' from
names or yin-yang. Marker fragments can span tokens. Smaller rules cover
Greek relatives, Slavic pronouns, Vietnamese noun heads, and English 'which'
after a preposition or demonstrative. These are lexical approximations, not
a parser: matching fragments can also occur inside unrelated words.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
SCANDINAVIAN = {
    'som': -5.0, 'det': -3.8, 'den': -2.7, 'der': -4.9,
    'att': -0.9, 'du': -1.4, 'vi': -1.0, 'om': -0.4,
}
ARABIC_RELATIVES = {
    'التي', 'الذي', 'الذين', 'اللاتي', 'اللواتي',
    'اللذان', 'اللتان', 'اللذين', 'اللتين',
}
PRONOUNS_AND_NOUN_HEADS = {
    'người': -0.8, 'điều': -1.7, 'những': -0.55,
    'который': -0.6, 'которая': -0.27, 'которые': -0.23,
    'которого': 0.67, 'которым': -0.73, 'który': -0.9, 'która': -0.5,
    'whose': 0.26, 'whom': 0.53, 'where': -0.11,
}
BEFORE_WHICH = {
    'that': -1.4, 'those': -0.45, 'of': 0.7, 'after': 1.4,
    'among': 1.4, 'by': 0.35, 'through': 0.3, 'to': 0.2, 'from': 0.15,
}
LANGUAGES = ('en', 'de', 'nl', 'fr', 'es', 'it', 'pt',
             'sv', 'da', 'nb', 'id')

@lru_cache(maxsize=8192)
def frequencies(word):
    return tuple(zipf_frequency(word, lang) for lang in LANGUAGES)


def language(text):
    """Pick the language whose recent words have the highest frequencies."""
    words = re.findall(r'[^\W\d_]{2,}', text.lower())[-16:]
    if not words:
        return ''
    scores = [0.0] * len(LANGUAGES)
    for word in words:
        for i, frequency in enumerate(frequencies(word)):
            scores[i] += frequency
    return LANGUAGES[max(range(len(scores)), key=scores.__getitem__)]


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    boundary = not history or not history[-1].isalpha() or token[:1].isspace()
    value = 0.0

    # Whole words, with language disambiguation for shared Latin spellings.
    if lower == 'yang' and boundary:
        value = (-10.3 if language(history) == 'id' else
                 -4.0 if word[0].isupper() else -2.5)
    elif lower in SCANDINAVIAN and boundary and word != 'Som':
        if language(history) in ('sv', 'da', 'nb'):
            value = SCANDINAVIAN[lower]
    elif word.lstrip('و') in ARABIC_RELATIVES:
        value = -6.4
    elif word == 'ذ' and history.endswith('ال'):
        value = -4.7
    elif word == 'ذي' and history.endswith('الل'):
        value = -7.0
    elif word and len(word) <= 3 and (history + word).lower().endswith('yang'):
        value = -10.3 if language(history) == 'id' else -5.0

    # Thai marker pieces: ที่ (relative), กี่ (how many), พี่ (elder sibling).
    elif word == 'ท':
        value = -4.3
    elif word == 'ี่':
        value = (-10.6 if history.endswith('ท') else
                 4.1 if history.endswith('ก') else
                 -2.3 if history.endswith('พ') else 0.3)
    elif word and len(word) <= 5:
        joined = history[-5:] + word
        for marker, strength in (('ซึ่ง', -6.0), ('อัน', -6.5),
                                 ('อย่าง', -6.0), ('ที่', -10.6)):
            if joined.endswith(marker) and len(word) <= len(marker):
                value = strength
                break

    # Greek 'that' and 'which/where', including split spellings.
    if word and len(word) <= 3:
        joined = history[-5:] + word
        if joined.endswith(('ότι', 'ὅτι')):
            value = -3.0
        elif joined.endswith('που'):
            value = -5.5
    if boundary:
        value = PRONOUNS_AND_NOUN_HEADS.get(word, value)
    if lower == 'which' and boundary:
        previous = re.findall(r'[^\W\d_]+', history.lower())
        if word[0].isupper():
            value = 0.4
        elif not previous:
            value = -1.0
        else:
            value = BEFORE_WHICH.get(previous[-1], 0.0)
    return (doc, (history + token)[-600:]), value

"""A lexical detector of interruptions, hesitations, and contrastive turns.

Wait/Hmm give large negative responses; conjunctions and many fillers
are weaker. Capitalization, clause boundaries, and a few short phrases
separate discourse uses from ordinary uses. A comma can prolong a hesitation.
A short suffix joins split words; state resets at document boundaries.
Separate rules cover repeated middle-dot padding and the document-opening
strings '12' and 'Title:', both unusually strong training responses.
"""
import re

READS = ()

# Contrastive and explanatory conjunctions in several languages.
CONNECTIVES = {
    'but': -0.92, 'pero': -1.4, 'mais': -1.7, 'mas': -2.9,
    'ma': -2.0, 'aber': -0.95, 'ale': -3.2, 'maar': -1.6,
    'men': -2.4, 'ama': -1.1, 'но': -1.15, 'однако': -0.95,
    'doch': -0.9, 'denn': -1.0, 'sondern': -0.85,
    'لكن': -1.1, 'بل': -1.4, 'nhưng': -1.0, '하지만': -1.25,
}
CHINESE = {
    '但是': -0.9, '不過': -1.6, '不过': -1.1, '可是': -1.5,
    '然而': -0.65, '但': -0.8, '而': -0.25, '那么': -0.5,
    '所以': -0.3, '因为': -0.2, '因為': -0.2,
}
PHRASES = {
    'wait a second': -1.5, 'wait a minute': -2.7,
    'hold on': -3.7, 'hang on': -2.6, 'come on': -2.3,
    'i mean': -2.5, 'you know': -1.0, "let's see": -1.2,
    'let me see': -0.9, 'by the way': -2.7, 'in any case': -1.2,
    'all right': -1.6, 'oh my god': -1.5,
}
COMMA = {
    'hmm': -0.75, 'well': -0.7, 'okay': -1.1, 'actually': -0.9,
    'oh': -2.0, 'ah': -2.0, 'uh': -2.2, 'um': -2.0,
    'yeah': -0.8, 'no': -1.8, 'know': -1.7, 'mean': -1.5,
    'right': -1.1, 'look': -1.8,
}
PHRASE = re.compile(r'\b(' + '|'.join(map(re.escape, PHRASES)) + r')\Z')
WORD = re.compile(r'([^\W\d_]+)\Z')
PAUSE = re.compile(r'(?:h+m+|u+h+|h+u+h+|m{3,}|o+h+|a+h+|u+g+h+|a+w{2,})$')


def advance(carry, raw, doc):
