    text = (tail + raw).decode('utf-8', 'replace').replace('\\n', '\n')
    match = WORD.search(text)
    word = match[1] if match else ''
    lower = word.lower()
    capital = word.istitle()
    clause = not previous or bool(re.search(r'[,.;:!?\n—–]', previous))
    val = 0.0

    if lower in CONNECTIVES:
        val = CONNECTIVES[lower]
        if capital:
            val *= 1.5
        if lower in {'ma', 'mais', 'mas', 'ale', 'men'}:
            val = -0.15
            if not capital and re.search(r'[,;]', previous):
                val = CONNECTIVES[lower]
            elif capital and clause:
                val = -2.6 if lower == 'mais' else -1.8
        if word in {'Но', 'Aber', 'Pero'} and lower not in s.lower():
            val = -3.5
        if lower == 'but':
            if not capital and s == 'but':
                val = -1.4
            if previous_word in {'wait', 'hmm'}:
                val = -2.4
            elif previous_word in {'help', 'nothing', 'anything', 'all'}:
                val = -0.1
            elif not capital and re.search(r'[;:.—–]', previous):
                val = -1.45
        if word == 'Aber':
            val = -2.7
    elif lower == 'wait':
        val = -2.65 if capital or clause else -1.1
        if previous_word in {'wait', 'but', 'oh', 'well'}:
            val = -3.3
        if s.startswith('.'):
            val = -0.85
    elif lower in {'waiting', 'waits', 'waited', 'awaits'}:
        val = -0.85
    elif PAUSE.fullmatch(lower) and not word.isupper():
        if lower.startswith('hm') or lower.startswith('mm'):
            val = -2.45 if s.startswith(' ') else -2.1
        elif capital or clause or previous_word in {'oh', 'ah'}:
            val = -1.5
        if lower not in s.lower():
            val = -3.1
    elif lower == 'well':
        val = -1.5 if capital or clause else 0.0
        if previous_word == 'oh':
            val = -3.5
    elif lower == 'hold' and (clause or previous_word == 'wait'):
        val = -1.2
    elif lower == 'however':
        val = -0.15
        if capital:
            val = -0.65 if s.startswith(' ') else -0.9
    elif lower == 'so':
        val = -0.55 if capital else -0.15
    elif lower in {'а', 'и', 'und', 'et'} and (clause or capital):
        val = -0.6
    elif lower == 'and':
        val = -0.5 if capital else 0.0
    elif lower == 'actually':
        val = -0.85 if capital or clause or previous_value < -0.7 else 0.0
    elif lower in {'yeah', 'yep', 'oui'}:
        val = -1.2
    elif lower in {'okay', 'alright', 'hey', 'wow'}:
        val = -0.65 if capital or clause else -0.25
    elif lower == 'ну':
        val = -3.0 if word == 'Ну' else -1.3
    elif lower in {'right', 'look'} and (clause or capital):
        val = -0.7 if lower == 'right' else -1.0
        if previous_word in {'oh', 'ah'}:
            val = -2.3
    elif lower == 'um' and capital:
        val = -0.9
    elif lower == 'yes':
        val = -0.35
    elif lower == 'no':
        if previous_word in {'wait', 'hmm'}:
            val = -2.65
        elif previous_word == 'oh':
            val = -3.0
        elif previous_word in {'but', 'actually'}:
            val = -1.3
        elif '?' in previous:
            val = -1.0
    elif lower in {'now', 'because', 'therefore', 'thus'}:
        val = -0.3 if capital else 0.0
    elif lower == 'yet':
        val = -0.9 if capital else (-0.45 if clause else 0.0)

    for conjunction, strength in CHINESE.items():
        if text.endswith(conjunction):
            val = strength
            break
    if text.endswith(('けど', 'ますが')):
        val = -0.6
    if text.endswith('是啊'):
        val = -2.2
    elif text.endswith(('啊', '呃', '嗯')):
        val = -1.1
    phrase = PHRASE.search(text.lower())
    if phrase:
        val = PHRASES[phrase[1]]
        if phrase[1] in {'hold on', 'come on', 'hang on'}:
            lead = text.lower()[:phrase.start()].rstrip(' \t\r')
            literal = (lead and lead[-1] not in ',.;:!?\n'
                       and not lead.endswith('wait'))
