        if previous_word == 'wait':
            val = previous_value * 0.85
        elif previous_word in COMMA:
            val = COMMA[previous_word]
    if s == '，' and previous_word.endswith(('啊', '呃', '嗯')):
        val = -1.4
    if text in {'12', 'Title:'}:
        val = -4.95
    if s == '··' and previous == s:
        val = -2.8

    comma = s.strip() == ',' and '\n' not in s
    remember = previous_word if comma else lower
    return (doc, (tail + raw)[-48:], s, remember, val), val


def step(carry, prefix, upstream):
    return advance(carry, prefix.token_bytes[-1], prefix.document_ids[-1])

"""Recognize short ao vowel spellings, mainly across token boundaries.

An a-ending token followed by an o-starting token gives the main positive
response; zero is a weaker o look-alike. Transliteration extends this rule to
accents and several alphabets. Short Latin ao syllables also respond, with
larger values for three-letter capitalized ao spellings. Spaces and long tokens
weaken the match. Chinese readings and hiragana particles are not interpreted
as Latin spelling. Other text is near zero; document starts instead receive
a negative constant. The rules approximate the pattern, not token-specific strength.
"""
from functools import lru_cache
from anyascii import anyascii
import regex

READS = ()

# Strengths for one-letter, short (2-3), and longer o-starting tokens.
VOWEL_STRENGTH = {
    'Latin': (4.0, 4.2, 1.0),
    'Cyrillic': (8.5, 3.0, 0.1),
    'Greek': (3.5, 0.5, 0.1),
    'Katakana': (6.5, 2.0, 0.1),
    'Thai': (1.5, 0.0, 0.0),
}


@lru_cache(maxsize=16384)
def spelling(text):
    if regex.search(r'\p{Script=Han}|\p{Script=Hiragana}', text):
        return '', 'Latin'
    for script in ('Cyrillic', 'Greek', 'Katakana', 'Thai'):
        if regex.search(fr'\p{{Script={script}}}', text):
            return anyascii(text).lower(), script
    return anyascii(text).lower(), 'Latin'


def response(previous, text):
    p, _ = spelling(previous)
    s, script = spelling(text)
    if s.startswith(('o', '0')) and p.endswith('a'):
        if s.startswith('0'):
            return 1.3
        # Closed 'or' syllables are much weaker than an open o vowel.
        if script == 'Latin' and len(s) >= 3:
            if s.startswith('or') and s[2] not in 'aeiou':
                return 0.4
        size = 0 if len(s) == 1 else 1 if len(s) <= 3 else 2
        return VOWEL_STRENGTH[script][size]
    if text == ' O' and p.endswith('a'):
        return 0.8
    if s.startswith('iao'):
        return 3.2
    bare = s.strip(' .-_')
    if bare.startswith('ao'):
        if p.endswith('o'):
            return 4.5
        if 'ã' in text:
            return 0.6
        if s.startswith(' '):
            return 2.0 if text.strip()[:1].isupper() else 0.8
        return 3.2
    if len(bare) <= 4 and bare.endswith('ao'):
        capital = text.strip(' .-_')[:1].isupper()
        if 'ã' in text:
            return 1.5 if capital else -0.001
        if capital:
            if s.startswith(' '):
                return 6.0 if len(bare) == 3 and text.strip().isascii() else 0.6
            return 1.8
        return 5.5 if s.startswith('.') else 0.1
    return -0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    new = carry is None or carry[0] != doc
    value = -0.185 if new else response(carry[1], text)
    return (doc, text), value

"""An opening-position signal, especially strong for Korean syllables.

Training examples are mostly quiet after the first token changes. At the
opening, script and token format explain part of the strength; rare and
capitalized Latin words tend to give a larger response than short common ones.
Dot leaders and caret fills are two strong formatting cases. The broad
classes deliberately omit the remaining word-by-word variation.
"""
import regex
from wordfreq import zipf_frequency

READS = ()
SCRIPT_STRENGTHS = (
    ('Hangul', 24.0),
    ('Katakana', 7.0),
    ('Hiragana', 2.0),
    ('Thai', 5.0),
    ('Han', 0.5),
)


def opening_value(token_text):
    text = token_text.strip()
    for script, strength in SCRIPT_STRENGTHS:
        if regex.search(r'\p{Script=' + script + '}', text):
            return strength
    if text == '<|im_start|>':
        return 2.0
    if text == '<|endoftext|>':
        return -3.8
    # Decorative dot leaders and caret fills also have large opening pulses.
    if len(text) >= 2 and set(text) == {'·'}:
        return 7.8
    if len(text) >= 4 and set(text) == {'^'}:
        return 11.2
    if '\ufffd' in text:
        return 2.6  # A replacement character or partial Unicode token.
    if not text:
        return 0.0
    if text.isascii() and text.isalpha():
        return (1.2 - 0.14 * zipf_frequency(text, 'en')
                + 0.55 * text.istitle() - 0.6 * (len(text) <= 2)
                - 0.2 * token_text.startswith(' '))
    if any(ch.isalpha() for ch in text):
        return 1.3  # Other scripts, or an identifier joined to punctuation.
    return -0.1  # Numbers and punctuation have little opening response.


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_ids[-1]
    if carry is None or carry[0] != doc:
        opening_token, still_opening = token, True
    else:
        _, opening_token, still_opening = carry
        still_opening = still_opening and token == opening_token
    value = opening_value(prefix.token_strings[-1]) if still_opening else 0.0
    return (doc, opening_token, still_opening), value

"""Approximate a boundary/formatting signal, not a semantic word detector.

Most tokens get a near-zero background. At document starts, short alphabetic
pieces, Cyrillic text and whitespace shift the prediction downward; a leading
space shifts it upward. A tab and an HTML declaration opener have stronger
boundary responses. Paired middle dots and initial repository metadata
headers have separate formatting responses. Content-word-specific variation is omitted.
"""
import regex

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    s = prefix.token_strings[-1]
    if first:
        position, opening = 0, s
    else:
        position = carry[1] + 1
        opening = (carry[2] + s) if position < 5 else ''

    value = 0.0016
    if first:
        word = s.strip()
        value = -0.12
        if s.startswith(' '):
            value += 0.10
        if word.isalpha() and len(word) == 1:
            value -= 0.17
        elif word.isalpha() and len(word) == 2:
            value -= 0.16
        if s.isspace():
            value -= 0.18
        if regex.search(r'\p{Script=Cyrillic}', s):
            value -= 0.23
        if s == '\t':
            value = -1.59
        elif s == '<!':
            value = 3.65
        elif s == '<':
            value = 0.337
        elif s == '<|im_start|>':
            value = -0.28
    elif opening == '<reponame':
        value = 1.02
    elif opening == '<gh_stars':
        value = 0.73

    if s == '··':
        value = -0.80

    return (doc, position, opening), value

"""A web-address-ending signal, not a general dot or punctuation signal.

Recognize lowercase top-level domains. Most country codes and newer endings
need an address cue. Longer, multiply dotted hostnames get larger responses;
academic and nonprofit endings are strongest. Suppress programming namespaces.
An explicit web prefix slightly lowers amplitude; Wikipedia raises it.
A following slash retains a weak path signal; .github itself is mildly negative.
The rest of ordinary text is approximately silent.
"""
import re
import pycountry

READS = ()
COUNTRIES = {c.alpha_2.lower() for c in pycountry.countries} | {'uk', 'eu', 'su'}
BASE = {'com': 3.7, 'org': 5.6, 'edu': 8.2, 'net': 6.0,
        'gov': 2.8, 'io': 4.0, 'co': 1.5}
NEW_DOMAINS = set('info biz mobi travel online site xyz me tv ai dev app cloud '
                  'shop tech pro name int design work today'.split())
HOST = re.compile(r'[A-Za-z0-9_.-]+$')
ADDRESS = re.compile(r'(?:://|www\.|@)[A-Za-z0-9_.-]*$')
WEB = re.compile(r'(?:://|www\.)[A-Za-z0-9_.-]*$')
NAMESPACE = re.compile(r'\b(?:import|package) [\w.]*$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0.0)
    _, tail, previous, last_domain = carry
    token = prefix.token_strings[-1]
    suffix = token[1:] if token.startswith('.') else ''
    value = domain = 0.0
    if suffix in BASE or suffix in COUNTRIES or suffix in NEW_DOMAINS:
        match = HOST.search(tail)
        stem = match.group() if match else ''
        cue = ADDRESS.search(tail) or re.search(r'\.(edu|gov|co|ac)$', stem)
        code = NAMESPACE.search(tail) or stem in {
            'java', 'android', 'javax', 'System', 'plt'}
        if not code and (suffix in BASE or cue):
            base = BASE.get(suffix, 3.2 if suffix in COUNTRIES else 1.0)
            value = base + .24 * min(len(stem), 35)
            value += 1.7 * min(stem.count('.'), 3)
            if '@' in tail[-len(stem)-1:]:
                value -= .4
            if WEB.search(tail):
                value -= 1.65
            if stem.endswith('wikipedia'):
                value += 7.3
            domain = value
    elif token == '/':
        value = .25 * last_domain
        if previous in {'.github', '.git'}:
            value = 1.5
    elif token == '.github':
        value = -.8
    return (doc, (tail + token)[-180:], token, domain), float(value)

"""Local quotation/source attribution, not speech-topic classification.
The largest responses are to 'said' just after a quotation and to 'to' in
'detached' uses of 'according to'. Ordinary reporting clauses are much weaker.
Small spelling sets recognize analogous constructions in several languages.
Keep two tokens and 100 characters of history, resetting between documents.
"""
import re

READS = ()
REPORT = set(('explained explains reported reports stated states noted notes '
              'added adds continued continues wrote writes asked asks '
              'whispered murmured muttered shouted returned interrupted '
              'remarked observed insisted declared announced').split())
EXPRESSIVE = {'replied', 'cried', 'answered', 'exclaimed'}
FOREIGN = set(('sagte sagt dijo dice dit répond ajout '
               'сказал сказала говорит говор рассказал рассказ '
               'сообщ сообщает заявил отметил отмет ответ продолж добав '
               'قال وقال يقول').split())
RUSSIAN_STEMS = set('говор рассказ сообщ ответ продолж добав отмет заяв'.split())
# Reporting words whose inflections are often split across tokens.
COMPLETION = re.compile(
    r"\b(?:s['’]écria|déclar[aé]|répondit|reprit|explique|"
    r"säger|menurut|dijo|spiegato|señala)$")


def quote_end(text):
    return bool(re.search(r'[\"\'”’»」』“],?$', text.strip()))


def predict(token, previous, before_previous, tail):
    word, prev = token.strip(), previous.strip()
    quoted = quote_end(previous)
    punctuation = quoted or prev in {',', ':', ';', '!', '?', '—', '–', '-', '،'}
    if word == 'to' and re.search(r'\baccording$', tail, re.I):
        left = re.sub(r'\baccording$', '', tail, flags=re.I).rstrip(' ')
        if not left or left[-1] in ',.;:!?\n\"”’»(-–—':
            return 4.5
        if re.search(r'\b(but|so|wait|and|okay)\s*$', left, re.I):
            return 3.3
        return 1.0
    if word.lower() in {'selon', 'según', 'laut'}:
        return 2.3
    if word == 'словам' or (word == 'ению' and prev == 'мн'):
        return 7.3
    if (word == 'мн' and prev.lower() == 'по') or (
        word in {'acordo', 'acuerdo'} and prev.lower() == 'de'
    ):
        return 1.3
    if word in {'com', 'con'} and prev in {'acordo', 'acuerdo'}:
        return 1.9
    if word in {'据', '據', '根据', '根據'}:
        return 0.8
    if word in {'という', 'と言う', 'と言', 'いう', 'と言われ'}:
        return 0.8
    if word in {'」と', '』と'} or (word == 'と' and quoted):
        return 1.1
    if word in {'라고', '이라고', '다고', '고'} and quoted:
        return 2.2
    if re.fullmatch(r',(?:"|”|’|\'\')', word):
        prose = any(c.isalpha() for c in prev)
        return 1.1 if prose and not prev.endswith((')', ']', '}')) else 0.2
    if word in {'?"', '!"', '?”', '!”', '？”', '！”'}:
        return 0.2
    if token in {' -', ' –', ' —', ' --'} and quoted and prev.endswith(','):
        return 4.0
    if token in {' he', ' she'} and quoted:
        return 1.7

    # Preserve case and leading spaces: 'Say' may just begin a name.
    if token.startswith(' ') and word == word.lower():
        if word in {'said', 'says'}:
            if quoted:
                return 7.7 if word == 'said' else 5.9
            if punctuation:
                return 2.5
            if quote_end(before_previous):
                return 0.5
            return 0.2 if prev in {'he', 'she', 'I'} else 0.0
        if word in EXPRESSIVE:
            return 9.6 if quoted else 0.7
        if word in REPORT:
            return 5.5 if quoted else (0.8 if punctuation else -0.1)
        if word in FOREIGN:
            if quoted or (prev in {'-', '–', '—'} and quote_end(before_previous)):
                return 6.3
            if punctuation:
                return 3.7
            return 4.2 if word == 'sagte' else 0.5
    if word in {'ил', 'ила', 'или', 'ал', 'ала', 'али', 'ает', 'ится'}:
        if prev in RUSSIAN_STEMS:
            return 4.1
    if word and not token.startswith(' ') and COMPLETION.search(tail + token):
        return 5.5
    if word == 'ال' and prev == 'وق':
        return 5.7
    if word == 'قال' and (not prev or prev[-1] in '.،\n' or prev == 'و'):
        return 5.7
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '')
    _, previous, before_previous, tail = carry
    token = prefix.token_strings[-1]
    value = predict(token, previous, before_previous, tail)
    return (doc, token, previous, (tail + token)[-100:]), value

programs.haiku:
"""Speech-attribution detector (final).

Layer-1 MLP feature that fires on the words that attribute a quotation to a speaker or
source. Predicted activation, by the current token and the tokens just before it:
- a speech verb (said, says, sagte, dijo, сообщает, говорит, ...) right after a closing
  quotation mark, as in '...," said James': strong (6);
- a speech verb elsewhere: weak (0.5);
- 'to' right after 'according' (according to): 2.5;
- 'словам' after 'По' (according to, Russian), and 'laut' / 'según' (according to,
  German / Spanish): 2-3;
- a closing quotation mark itself: weak (0.8), since it often precedes an attribution.
Everything else is 0. All values are multiplied by SCALE = 0.4, which the
variance-explained fit chose (predictions at full size overshoot).
"""

READS = ()
SCALE = 0.4

SPEECH_VERBS = {
    "said", "says", "say", "dijo", "sagte", "sagt", "répond", "dit", "сообщает",
    "говорит", "говор", "elas", "jelasnya",
}
CLOSE_QUOTES = {',"', ',”', '."', '.”', '”', '"', '」と', '」'}


def _norm(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = _norm(toks[-1])
    prev = _norm(toks[-2]) if len(toks) > 1 else ""
    after_quote = any(t in CLOSE_QUOTES or t.endswith(('"', '”')) for t in toks[-3:-1])
    if cur in SPEECH_VERBS:
        return None, SCALE * (6.0 if after_quote else 0.5)
    if cur == "to" and prev == "according":
        return None, SCALE * 2.5
    if cur == "словам" and prev == "по":
        return None, SCALE * 3.0
    if cur in ("laut", "según"):
        return None, SCALE * 2.0
    if toks[-1].strip() in CLOSE_QUOTES or toks[-1].strip().endswith(('"', '”')):
        return None, SCALE * 0.8
    return None, 0.0

programs.sol:
"""A partial approximation: opening digits, capitalization, and forms of 'in'.

At a document's opening, digit responses generally rise with digit value;
leading zeroes are especially negative. The opening digits 12 instead cause
an exceptionally large negative response on the 2. Initial capitalization
provides a coarse baseline for other opening tokens.

Away from the opening, selected Iberian/Slavic forms of 'in' are negative.
Word-frequency evidence in preceding text distinguishes these forms from
identically spelled fragments in other languages. Other tokens get a small
constant. State resets at document boundaries.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
LANGUAGES = ('en', 'es', 'pt', 'pl', 'fr', 'de', 'nl', 'tr', 'cs', 'sk')
IN_FORMS = {'es': ('en', -0.28), 'pt': ('em', -0.26),
            'pl': ('w', -0.23), 'cs': ('v', -0.13),
            'sk': ('v', -0.13)}


@lru_cache(maxsize=32768)
def frequency(word, language):
    return zipf_frequency(word, language)


def language_of(text):
    words = re.findall(r'[^\W\d_]{2,}', text.lower())[-16:]
    if not words:
        return ''
    return max(LANGUAGES, key=lambda lang: sum(
        frequency(word, lang) for word in words))


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        position, previous, recent, digit_run = 0, '', b'', True
    else:
        _, position, previous, recent, digit_run = carry
        position += 1
        digit_run = digit_run and token == previous
    value = -0.0025
    if position == 0 and token:
        if token[0].isupper():
            value = 0.06 if len(token) == 1 else 0.29
        elif token[0].isdecimal():
            value = -0.16
        elif token.lstrip()[:1].islower():
            value = 0.08
        elif not token[0].isspace():
            value = -0.02
    if digit_run and len(token) == 1 and '0' <= token <= '9':
        value = -0.566 if token == '0' else -0.456 + 0.1015 * int(token)
    word = token.strip().lower()
    boundary = (not recent or token[:1].isspace() or
                not recent.decode('utf-8', 'ignore')[-1:].isalpha())
    if boundary:
        if word == 'в':
            value = -0.10
        elif word in {'en', 'em', 'w', 'v'}:
            lang = language_of(recent.decode('utf-8', 'ignore'))
            if lang in IN_FORMS and IN_FORMS[lang][0] == word:
                value = IN_FORMS[lang][1]
    if position == 1 and previous == '1' and token == '2':
        value = -3.16
    recent = (recent + prefix.token_bytes[-1])[-768:]
    return (document, position, token, recent, digit_run), value

"""A partial, typography-based approximation of the component.

Internal padding, long unwrapped-line ellipses, soft hyphens, form-feed cues,
and repeated middle-dot leaders receive negative values. Table pipes have a
small context-dependent adjustment. Document-initial tokens get a separate
length/case correction. Most ordinary-word and hard-hyphen variation is omitted.

State holds the current line, last token, and a count of preceding prose wraps;
it resets at document boundaries. Both real and escaped newlines end a line.
"""

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    if first:
        previous, line, wraps = '', '', 0
    else:
        _, previous, line, wraps = carry
    text = s.strip()
    length = len(line)
    code = sum(ch in '{}=;_<>$\\' for ch in line)
    prose = sum(ch.isalpha() for ch in line) / (length + 1)
    value = 0.0

    if first:
        if s.startswith('<|'):
            value = 0.0
        elif text == '•':
            value = -1.45
        elif len(text) >= 6:
            value = -0.40
        elif len(text) >= 2:
            value = -0.27
        elif text.istitle():
            value = -0.08
        elif text.isdigit():
            value = -0.17
        else:
            value = -0.23
    elif s.isspace() and '\n' not in s and '\r' not in s:
        # Padding inside a line, as opposed to leading indentation.
        n = len(s)
        if n >= 32:
            value = -1.1 if length > 10 else -0.1
        elif n >= 20 and length > 16:
            value = -0.63
        elif n >= 2 and length > 16:
            value = -0.08
        elif s == '\t':
            value = -0.035
    elif s == '\\x' and length < 10:
        value = -0.5
    elif '...' in s and length > 147 and wraps == 0:
        value = -0.30 if len(s) <= 3 else -0.06
    elif text and not text.strip('|'):
        if len(s) >= 2 and length > 22:
            value = -0.20 if previous[-1:].isspace() else -0.04
        elif len(s) == 1 and prose > 0.03:
            value = 0.12

    if '\xad' in s:
        value = -2.4
    if '\x0c' in s:
        value = -0.48
    if len(text) >= 2 and not text.strip('·'):
        value = -0.56

    normalized = s.replace('\\n', '\n').replace('\\r', '\r')
    if '\n' in normalized:
        if length > 45 and prose > 0.6 and code < 2:
            wraps = min(wraps + 1, 5)
        line = normalized.rsplit('\n', 1)[-1]
    else:
        line = (line + normalized)[-300:]
    return (doc, s, line, wraps), value

"""A spelling-sensitive approximation, not a general awareness classifier.

The main triggers are aware/awareness, beware/wary, warehouse, and the fragments ware,
eware and wise. Case and whether a token includes its leading space matter.
A smaller response occurs on a word continuation after w, especially wahr
(the German 'true' root). Chinese warehouse spellings are separate triggers.
The Japanese spelling of ware and partial bytes of traditional 倉 also
respond. Everything else is zero; small or unrelated responses are missed.
"""
import re

READS = ()
TRADITIONAL_WAREHOUSE = '倉'.encode('utf-8')


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    word = s.strip().lower()
    previous = ''
    if (prefix.position and
            prefix.document_ids[-1] == prefix.document_ids[-2]):
        previous = prefix.token_strings[-2].lower()
    value = 0.0

    if re.fullmatch(r'-?(un)?aware(ness)?', word):
        value = 4.8
        if not s.startswith(' '):
            value = 6.4
            if s.startswith('A'):
                value = 11.0
    elif word in ('beware', 'wary'):
        value = 5.0 if word == 'beware' else 3.0
    elif word in ('warehouse', 'warehouses'):
        value = 4.8
    elif word == 'ware':
        value = 4.5 if s.startswith(' ') else 1.7
        if s.strip() == 'WARE':
            value = 12.5
    elif s == 'eware':
        value = 3.9
    elif word.strip('-') == 'wise':
        value = 1.0
    elif word in ('仓', '倉'):
        value = 8.0
    elif word in ('仓库', '倉庫'):
        value = 5.0
    elif word in ('仓储', '倉儲'):
        value = 3.0

    if s.isalpha() and previous.endswith('w'):
        onset = s.lower()
        if onset == 'are' and previous.endswith('bew'):
            value = 8.5
        elif onset.startswith('ahr'):
            value += 8.0
        elif onset.startswith('ah'):
            value += 2.0
        elif onset.startswith('ar'):
            value += 0.8
        elif onset.startswith('a'):
            value += 0.6
        elif onset.startswith('is'):
            value += 1.3
        elif onset.startswith(('e', 'i', 'r')):
            value += 0.1
    if word in ('house', 'houses') and previous.endswith('ware'):
        value = 8.0

    # These are local spelling tests, including incomplete UTF-8 characters.
    token_bytes = prefix.token_bytes[-1]
    count = 1
    while (count < min(3, prefix.position + 1) and
           prefix.document_ids[-count - 1] == prefix.document_ids[-1]):
        count += 1
    recent = b''.join(prefix.token_bytes[-count:])
    if token_bytes == TRADITIONAL_WAREHOUSE[:-1]:
        value = 2.2
    elif (token_bytes == TRADITIONAL_WAREHOUSE[-1:] and
          recent.endswith(TRADITIONAL_WAREHOUSE)):
        value = 14.0
    elif s == 'ア' and previous.endswith('ウェ'):
        value = 4.6
    elif s == 'ハウス' and recent.endswith('ウェアハウス'.encode('utf-8')):
        value = 6.0
    return None, value

"""A lexical approximation to a before/ahead/in-front detector.

Recognize precedence and preparation phrases, several translations, and
split vor-/voor- prefixes. Phrase endings and split spellings have their
own response sizes, calibrated on training text. This is not a semantic
parser: unrecognized patterns get zero. Keep only two previous tokens,
resetting at document boundaries.
"""
READS = ()

# German, Dutch, French, Spanish/Portuguese, Italian, Vietnamese, Arabic.
BEFORE_WORDS = {
    'vor': 6.0,
    'bevor': 6.0,
    'voor': 6.6,
    'avant': 7.2,
    'devant': 4.0,
    'antes': 9.0,
    'ante': 5.2,
    'prima': 3.6,
    'trước': 2.7,
    'قبل': 3.0,
}
PHRASES = {
    'in front': 4.4,
    'in advance': 4.9,
    'prior to': 4.2,
    'earlier than': 4.0,
}


def response(raw, previous, earlier):
    t = raw.strip().lower()
    p = previous.strip().lower()
    pp = earlier.strip().lower()
    spaced = bool(raw and raw[0].isspace())
    if t == 'before':
        return 1.4 if p == 'as' else (2.9 if spaced else 1.7)
    phrase = p + ' ' + t
    if phrase in PHRASES:
        return PHRASES[phrase]
    if t.lstrip('-') == 'of':
        if p == 'front':
            return 10.5 if pp == 'in' else 0.5
        if p in ('ahead', 'advance', 'eve'):
            return {'ahead': 8.6, 'advance': 12.0, 'eve': 7.5}[p]
    if t == 'for':
        if p == 'ready':
            return 3.2
        if p.startswith('prepar'):
            return 2.5
        if p == 'waiting':
            return 1.4
    if t == 'de' and p == 'antes' and previous[:1].isspace():
        return 5.0
    if spaced:
        if t in BEFORE_WORDS:
            return BEFORE_WORDS[t]
    elif t:
        # Prefixes split across tokens; distinguish them from whole tokens.
        if t in ('vor', 'voor'):
            return 4.4 if t == 'vor' else 4.6
        if p == 'vor' and t.isalpha():
            return 1.6
        if t.startswith('or') and p.endswith('v'):
            if p == 'v':
                return 9.5 if previous.endswith('V') else 6.4
            return 2.5
        if (t.startswith('oor') and p.endswith('v') or
                t.startswith('or') and p.endswith('vo')):
            return 6.9
        if t == 'fore' and p in ('be', 'a'):
            return 7.0
        if t in ('ant', 'anti') and p.lstrip("'’") in ('av', 'dav'):
            return 13.5 if previous.strip().istitle() else 6.8
        if t == 'es' and p == 'ant':
            return 10.1
    # Thai 'before', including a word split across tokens.
    if (p + t).endswith('ก่อน') and not p.endswith('ก่อน'):
        return 9.0
    if t in ('前', '之前', '以前'):
        return 0.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = earlier = ''
    else:
        previous, earlier = carry[1:]
    raw = prefix.token_strings[-1]
    return (doc, raw, previous), response(raw, previous, earlier)

"""Recognize local continuations of calendar/time expressions.

Ordinal endings after month/day dates are strongly negative, much more so
than ordinary ordinal endings. Spaces and connecting words that extend dates
are negative too; digits completing dates are mildly positive. Other rules cover several East Asian date/time units and code compounds
(such as Traceback, debuginfo and BytesIO), mostly with positive values.
Unrecognized text contributes zero. Only a short, document-local
text tail is retained; these rules do not parse or predict future tokens.
"""
import calendar
import re

READS = ()
_MONTH = '(?:' + '|'.join(
    list(calendar.month_name[1:]) + list(calendar.month_abbr[1:])
) + ')'
_WEEK = '(?:' + '|'.join(
    list(calendar.day_name) + list(calendar.day_abbr)
) + ')'
MONTH = re.compile(r'\b' + _MONTH + r'\.?$', re.I)
DATE = re.compile(r'\b' + _MONTH + r'\.?\s+(\d{1,4})(st|nd|rd|th)?$', re.I)
WEEK = re.compile(r'\b' + _WEEK + r'$', re.I)
WEEK_DATE = re.compile(r'\b' + _WEEK + r',?\s+(\d{1,2})$', re.I)
YEAR = re.compile(r'\b' + _MONTH + r'.{0,15}\d{4}$', re.I)
SEASON = re.compile(r'\b(?:spring|summer|autumn|fall|winter)$', re.I)


def activation(s, h):
    date = DATE.search(h)
    if s in ('st', 'nd', 'rd', 'th') and re.search(r'\d$', h):
        if date and len(date[1]) <= 2:
            return -16.5
        if WEEK_DATE.search(h):
            return -6.2
        return -0.35
    if s == ' ':
        if date:
            return -3.0 if date[2] else (-5.4 if len(date[1]) <= 2 else 0.0)
        if YEAR.search(h):
            return -1.1
    if MONTH.search(h):
        if s == ' of' and MONTH.search(h)[0][0].isupper():
            return -9.3
        if s in (' last', ' next'):
            return -5.7
        if s in (' to', ' through', ' thru', ' and', ' –', '-'):
            return -0.3
    if s == ' of' and date and len(date[1]) <= 2:
        return -4.0 if date[2] else -7.0
    if s == ' of' and (WEEK.search(h) or SEASON.search(h)):
        return -2.3
    if WEEK.search(h):
        if s == ' night':
            return 1.0
        if s in (' morning', ' afternoon', ' evening', ' evenings'):
            return -1.2
        if s in (' through', ' thru', ' following', ' every'):
            return -1.8
    if s == ' of' and re.search(r'\d(?:st|nd|rd|th)$', h):
        return -0.8
    if s == 'back' and h.lower().endswith('trace'):
        return 12.5 if h.endswith('Trace') else 4.0
    if s.strip() == 'traceback':
        return 5.8 if h.rstrip().endswith('import') else 3.5
    if s.lower() in ('info', ' info', '_info', '-info'):
        if h.endswith('debug'):
            return 8.5
        if h.endswith('Debug'):
            return 4.0
        if h.lower().endswith(('bmp', 'bitmap')):
            return 6.0
        if h.lower().endswith('monitor') and s.isupper():
            return 3.2
        if h.endswith('tsbuild'):
            return 5.2
        return 0.35
    if s == 'IO' and h.endswith(('Bytes', 'String')):
        return 2.1
    if s == '.data' and h.endswith('springframework'):
        return -2.8
    if s in ('点', '點', '号', '號', '일', '間'):
        if re.search(r'[\d一二三四五六七八九十两兩]+(?:日|週|周)?$', h):
            if s in ('点', '點'):
                return -3.5 if re.search(r'(上午|下午|晚上|凌晨).{0,4}$', h) else -1.0
            if s in ('号', '號'):
                return -8.0 if re.search(r'月\d+$', h) else 0.0
            return -1.1
    if s.isascii() and s.isdigit() and date:
        number = date[1]
        if len(number) == 1:
            if number == '3':  # the final days of a month
                return 1.15
            if s == '0':  # round day numbers
                return 0.55
            return 0.15
        if len(number) == 3:
            return 0.55 if number[0] == '1' else 0.08
        return 0.0
    if s == ',' and date and len(date[1]) <= 2:
        return 0.29
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = activation(token, tail)
    return (doc, (tail + token)[-160:]), value

programs.haiku:
"""Component layers.1.mlp.down_proj:4700: a date detector that goes negative.

Its large responses are all negative and sit at the end of a month-and-day date:
  * the ordinal suffix of a day after a month name ("April 25th", "June 15th"): very negative;
  * a space that follows a month and day and comes before a year or clock time
    ("Dec 16 12:", "December 15 2017"): negative;
  * "of" right after a month ("November of 2018"): negative.
An ordinal after a bare number with no month ("the 18th century") is only slightly negative.
Two small positive responses are code: a word tail such as "info" in "debug|info" or
"json|info", and "Trace|back" / "traceback" in Python error messages.
"""

READS = ()

MONTHS = {
    "January", "February", "March", "April", "May", "June", "July", "August",
    "September", "October", "November", "December", "Jan", "Feb", "Mar", "Apr",
    "Jun", "Jul", "Aug", "Sep", "Sept", "Oct", "Nov", "Dec",
}
ORDINAL_SUFFIXES = {"st", "nd", "rd", "th"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    n = len(tokens)
    cur = tokens[-1]
    prev = tokens[-2] if n > 1 else ""
    # the words of the last few tokens, only from the same document
    recent = [
        tokens[i].strip()
        for i in range(max(0, n - 6), n - 1)
        if docs[i] == docs[-1]
    ]
    month_near = any(word in MONTHS for word in recent[-4:])
    value = 0.0
    if cur in ORDINAL_SUFFIXES and prev.strip().isdigit():
        value = -16.0 if month_near else -0.4
    elif cur == " " and prev.strip().isdigit() and month_near:
        value = -5.5
    elif cur == " of" and prev.strip() in MONTHS:
        value = -9.0
    elif cur == "back" and prev == "Trace":
        value = 12.0
    elif cur == "traceback":
        value = 5.0
    elif cur == "info" and prev and not prev.startswith(" "):
        value = 3.0
    return carry, value

programs.sol:
"""Partial approximation by recognizable local syntax.

Template instructions/interpolations, markup bindings and repository markers
produce negative responses. Ordinary else/elif branches, brace-wrapped
math macros and several named code forms produce positive responses.
Additional clauses handle explicit API and code syntax. These were repeatable
patterns in training examples; constants are rounded activation averages.
Only a 160-character document-local suffix is kept, not a model or token table.
"""
import re

READS = ()

BINDINGS = {
    'if', 'else', 'for', 'show', 'hide', 'model', 'bind', 'on',
    'text', 'html', 'slot', 'repeat', 'class', 'style', 'include',
}


def activation(text, previous):
    word = text.strip()
    low = word.lower()
    if (previous + text).endswith(('<reponame', '<gh_stars')):
        return -4.84
    # Go/Handlebars-style interpolation and control directives.
    curly = previous.rfind('{{')
    if curly > previous.rfind('}}'):
        fragment = previous[curly + 2:].lstrip('- ')
        if not fragment and low in {'if', 'range', 'end', 'with', 'else',
                                    'template', 'define', 'block'}:
            return -10.11
        variable_start = (not fragment or re.fullmatch(
            r'(?:if|range|with)(?:\s+\$\w+\s*:=)?\s*', fragment))
        if word in {'.', '$'} and variable_start:
            return -6.96
        if word == '|':
            return -0.47
    # Django/Twig/Liquid {% instructions %}, and EJS <% instructions %>.
    start = max(previous.rfind('{%'), previous.rfind('<%'))
    end = max(previous.rfind('%}'), previous.rfind('%>'))
    instruction = previous[start + 2:] if start > end else None
    if word == '%' and previous.endswith('{'):
        return -2.40
    if instruction is not None:
        head = instruction.strip(' _-')
        if word.startswith('%'):
            if previous[start] == '<':
                return -1.77
            first = re.match(r'[A-Za-z]+', head)
            if first and len(first[0]) > 2:
                if word != '%':
                    return -0.46
                return (-4.96 if text[0].isspace()
                        else -2.43)
        if not head and word:
            if low.startswith('end'):
                return -6.94
            if low in {'if', 'for', 'set', 'include', 'extends', 'block',
                       'macro', 'with', 'import'}:
                if previous[start] == '<':
                    return -7.28
                if instruction.startswith('-'):
                    return -11.13
                return -8.24
            if low in {'auto', 'autoescape'}:
                return -3.47
            if low in {'trans', 'context', 'pluralize', 'plural'}:
                return -1.24
            if low in {'else', 'elif', 'elsif', 'unless', 'assign', 'capture',
                       'load', 'highlight', 'raw', 'filter', 'comment'}:
                return -5.77
            if word == '}':
                return -2.78
        if head == 'end' and word.isalpha():
            if low in {'block', 'for', 'if', 'macro', 'with', 'capture'}:
                return -5.90
            return -0.97
    php = previous.rfind('<?php')
    if php > previous.rfind('?>'):
        fragment = previous[php + 5:].strip()
        if not fragment and (low.startswith('end') or
                low in {'echo', 'if', 'foreach', 'require', 'include'}):
            return -2.84
        if word in {'$', '($'} and fragment in {'', 'echo', 'foreach'}:
            return -3.90
    if re.search(r'(?<![A-Za-z])(?:v|ng)$', previous):
        if low.startswith('-') and low[1:] in BINDINGS:
            return -5.71
    if (text == ':' and previous.endswith('v-slot')) or (
            word == '#' and previous.endswith('<template')):
        return -5.00
    if text == ':' and re.search(r'</?(?:asp|svelte|ui|dd|fx|x|xsl)$', previous):
        return -3.46
    if (text.isalpha() and
            re.search(r'</?(?:asp|svelte|ui|dd|fx|x|xsl):$', previous)):
        return -2.44
    if low == 'template' and previous.endswith(('<', '</')):
        return -1.87
    if low == '_template' and previous.endswith('render'):
        return -6.65
    if low == '_for' and previous.endswith('url'):
        return -10.91
    if text == 'template' and previous.endswith(('${', '$')):
        return -2.19
    if low.lstrip('._/') in {'template', 'templates'}:
        return -0.47
    if low in {'else', 'elif', 'elseif', 'elsif'}:
        if previous.rstrip().endswith('#'):
            return -0.48
        normalized = previous.replace('\\n', '\n').replace('\\t', '\t')
        line = normalized.rsplit('\n', 1)[-1]
        branch = (re.fullmatch(r'[ \t+/-]*(?:\d+\s*)?', line)
                  or previous.rstrip().endswith('}') or ' if ' in line)
        if branch:
            return 0.62 if low == 'else' else 0.28
        return -0.08
    if low == 'block' and re.search(r'display\s*:$', previous):
        return -2.57
    if low.lstrip('<') == 'typename' or (low == 'extends' and
            previous.rfind('<') > previous.rfind('>')):
        return -0.76
    if low == 'open' and previous.endswith('with'):
        return -0.46
    if word in {'($', ' ($'}:
        return -0.60
    if word == '$' and re.search(r'\bas$', previous):
        return -0.94
    if low == '_range' and previous.endswith('view'):
        return -2.07
    if text == 'style' and re.search(r'\\\s*display$', previous):
        if re.search(r'\{\s*\\\s+display$', previous):
            return 6.75
        if re.search(r'\{\s*\\display$', previous):
            return 3.60
        return -0.08
    if text == 'styles' and previous.endswith('template'):
        return 3.94
    if text == 'Element' and re.search(r'(?:HTML\w*|Jsx)$', previous):
        return 2.06
    if low == 'code' and previous.endswith('{@'):
        return 1.19
    if text == 'config' and previous.endswith('ts'):
        return 1.61
    if text == '.example' and previous.endswith('com'):
        return -5.69
    if low == 'end' and previous.endswith('<!--'):
        return -2.86
    if low == 'block' and previous.endswith('HTML'):
        return -1.85
    if low == 'href' and '<' in previous:
        return 0.15
    return 0.00125


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous = ''
    else:
        previous = carry[1]
    text = prefix.token_strings[-1]
    value = activation(text, previous)
    return (doc, (previous + text)[-160:]), float(value)

programs.haiku:
"""Layer-1 MLP component 4701 (down_proj), as a readable token-level program.

What it does: it is mostly silent, and it moves in a few recognisable places.
- Negative on template and loop identifiers in code: _range, _for, _FOR, template,
  _template, macro, gettext, namespace, and attribute-style fragments such as -text,
  -bind, -hide, and the placeholder package name .example (as in com.example).
- Negative on the words inside an open template tag ({% ... or <% ... not yet closed):
  end, if, include, trans, pluralize, block, for.
- Mildly negative on printf / template delimiters: %, ($, {{.
- Positive on code-style 'else' (after a closing brace or at the start of an indented
  line) and on a few class and config names: Element, InputElement, config, Inner, Outer.
Everything else predicts 0. Tag state is carried along the row and reset at a new document.
"""
READS = ()

TEMPLATE = {"template", "_template", "templates", "/template", "/templates", "macro",
            "gettext", "namespace", "fragment", "_block"}
LOOP = {"_range", "_for", "_FOR"}
ATTR = {"-text", "-bind", "-hide", "-dom", "-limit"}
PLACEHOLDER = {".example"}
DELIM = {"%", "($", "{{", "{%", "%}"}
TAG_WORDS = {"end", "if", "include", "trans", "endtrans", "pluralize", "block", "for"}
ELSE = {"else", "elif", "catch"}
TYPE = {"Element", "InputElement", "config", "Inner", "Outer", "Focus", "Welcome"}
TAG_OPEN = ("{%", "<%")
TAG_CLOSE = ("%}", "%>")


def step(carry, prefix, upstream):
    if carry is None or prefix.document_ids[-1] != carry["doc"]:
        carry = {"doc": prefix.document_ids[-1], "in_tag": False, "before": ""}
    s = prefix.token_strings[-1]
    word = s.strip()
    in_tag = carry["in_tag"]
    before = carry["before"]
    if word in LOOP or word in ATTR or word in PLACEHOLDER:
        v = -1.6
    elif word in TEMPLATE:
        v = -0.6
    elif in_tag and word in TAG_WORDS:
        v = -1.0
    elif word in DELIM and before.strip() in ('"', "'"):
        v = -1.5
    elif word in DELIM:
        v = -0.2
    elif word in ELSE:
        code = before.endswith("}") or before.strip() == "" or before.endswith("\n")
        v = 0.6 if code else -0.2
    elif word in TYPE:
        v = 0.4
    else:
        v = 0.0
    if any(c in s for c in TAG_CLOSE):
        in_tag = False
    if any(o in s for o in TAG_OPEN):
        in_tag = True
    return {"doc": carry["doc"], "in_tag": in_tag, "before": s}, float(v)

programs.sol:
"""Approximate short-range continuations of noun modifiers and markup endings.

After Japanese の (including この/その), assign stronger negative values
for spatial/time words, body-part words, and copula endings. Single kana
continuations also get negative values. After Chinese 的, usually predict a
small positive value; after Korean 의, distinguish unspaced word continuations.
Also cover main closing HTML/documentation tags, repeated middle dots, and a
few stock English expressions. These are coarse averages: word-specific
variation remains unexplained. Reset the two-token history at document changes.
"""
import regex

READS = ()
RELATIONS = frozenset('場内外前後上下中間際時度')
BODY_PARTS = frozenset('手足目耳口鼻顔頭身')
COPULAS = frozenset((
    'だ', 'だろう', 'だった', 'だが', 'だから', 'です', 'なの',
))


def response(previous, token, older=''):
    # Fixed phrases: an honorific, a document-viewing label, and "what's ...".
    if previous.strip() in ('Our', 'My') and token == ' Lady':
        return -4.8
    if previous.strip() == 'Full' and token == ' Document':
        return -4.0
    if previous in ("'s", '’s') and older.strip().lower() == 'what':
        if token == ' happening':
            return -0.9
        if token == ' more':
            return -2.3
    if (len(token) >= 2 and set(token) == {'·'}
            and previous and set(previous) == {'·'}):
        return -1.0
    if previous.endswith('</'):
        if token == 'body':
            return -7.4
        if token == 'html':
            return -5.2
        if token == 'head':
            return -2.4
        if token == 'DOCUMENT':
            return -5.8
        return 0.0
    if previous.endswith('の'):
        if token in RELATIONS:
            return -2.3
        if token in BODY_PARTS:
            return -1.8
        if token in COPULAS:
            return -2.4
        if regex.fullmatch(r'\p{Hiragana}+', token):
            return -1.4 if len(token) == 1 else -0.6
        if regex.fullmatch(r'\p{Han}', token):
            return -0.3
        if regex.fullmatch(r'\p{Katakana}+', token):
            return 0.15
        return 0.0
    if previous.endswith('的'):
        if regex.search(r'\p{Hiragana}', token):
            return -0.3
        return 0.14
    if previous.endswith('의'):
        if regex.search(r'\p{Hangul}', token):
            return -2.5 if not token.startswith(' ') else -0.2
        return 0.0
    return 0.001


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    older = carry[2] if carry is not None and carry[0] == document else ''
    value = response(previous, token, older)
    return (document, token, previous), value

programs.haiku:
"""Layer-1 MLP down_proj component 4702: a sparse, mostly negative detector.

Its activation is near zero on almost every token. It goes clearly negative in these cases:
1. A Japanese, Chinese or Korean noun right after a genitive particle (の, 의) or a demonstrative
   (この, その, あの). Location and formal nouns (場, 前, 内, 間, 手, 様, 度, ところ, ...) are
   strongly negative there; other nouns only slightly.
2. The name of a closing HTML tag (body, html, head, DOCUMENT) right after "</": about -5.
3. The first token of a document: fragments such as 's and ’s are negative, digits mildly
   negative, ordinary tokens slightly positive.
Everything else predicts 0.
"""
import regex

READS = ()

MARKERS = {"の", "의", "この", "その", "あの"}
FORMAL = set("場前内間下上外手仕様度明質")
CLOSE_TAGS = {"body", "html", "head", "DOCUMENT"}
CJK = regex.compile(r"[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}\p{Script=Hangul}]")


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        if tok[:1] in "'’":
            return carry, -0.6
        if tok.strip().isdigit():
            return carry, -0.26
        return carry, 0.07
    before = prefix.token_strings[-2]
    if before in MARKERS and CJK.search(tok):
        return carry, (-2.5 if tok in FORMAL else -0.3)
    if before == "</" and tok in CLOSE_TAGS:
        return carry, -5.0
    return carry, 0.0

programs.sol:
"""A lexical/syntactic approximation to a use-and-purpose signal.

Noun uses ("personal use", "industrial applications", "end user")
are stronger than verb uses ("they use", "can use").  Their following
"of" or "for" retains some of the signal.  Related purpose, source and
market nouns usually receive smaller responses. There are also explicit Chinese
and Romance-language equivalents, and a negative repeated-middle-dot rule.
These are local spelling and dictionary heuristics, not a sentence parser.
"""
from functools import lru_cache
import wordnet

READS = ()
USE = {'use', 'uses', 'usage', 'misuse', 'abuse',
       'utilization', 'utilisation', 'usefulness'}
PURPOSE = {'purpose', 'purposes', 'reason', 'reasons'}
SOURCE = {'source', 'sources', 'cause', 'causes'}
APPLICATION = {'application', 'applications'}
USER = {'user', 'users'}
MARKET = {'market', 'markets', 'audience', 'audiences'}
DETERMINER = {'the', 'a', 'an', 'this', 'these', 'those', 'any',
              'some', 'another', 'no', 'each', 'all'}
POSSESSIVE = {'my', 'our', 'your', 'its', 'his', 'her', 'their', "'s", '’s'}
VERB_CUE = {'to', 'can', 'will', 'would', 'should', 'could', 'may',
            'must', 'might', 'shall', 'do', 'does', 'did', 'i', 'you',
            'he', 'she', 'it', 'we', 'they', 'who', 'which'}
PREPOSITION = {'in', 'of', 'for', 'from', 'on', 'with', 'by', 'as'}
CENTRAL = {'main', 'primary', 'principal', 'major', 'core'}
# Nominal contexts strengthen 'use'; infinitives and subjects weaken it.
USE_AFTER = {'verb': 0.12, 'determiner': 1.25, 'preposition': 1.25,
             'possessive': 1.7, 'adjective': 2.3, 'noun': 0.65}

@lru_cache(maxsize=8192)
def grammar(word):
    parts = wordnet.parts_of_speech(word)
    if word in VERB_CUE:
        return 'verb'
    if word in DETERMINER:
        return 'determiner'
    if word in POSSESSIVE:
        return 'possessive'
    if word in PREPOSITION:
        return 'preposition'
    if 'adjective' in parts and 'adverb' not in parts:
        return 'adjective'
    if 'noun' in parts:
        return 'noun'
    return 'other'


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, last = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, last = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().strip('-_').lower()
    g = grammar(previous)
    boundary = token.startswith((' ', '-'))
    value = 0.0
    if word in USE:
        value = USE_AFTER.get(g, 0.35)
        if word not in {'use', 'uses'}:
            value = 1.4
        if not boundary:
            value = 0.15
        if token.startswith('-'):
            value = 5.0
    elif word in APPLICATION:
        value = 0.5 if word == 'application' else 1.3
        if g == 'adjective' and word == 'applications':
            value = 2.5
        if not boundary:
            value = 0.15
    elif word in USER:
        value = 0.3 if word == 'user' else 0.7
        if g == 'adjective':
            value = 0.75 if word == 'user' else 1.0
        if not boundary:
            value = 0.18
        if previous == 'end':
            value = 5.5
    elif word in PURPOSE | SOURCE:
        value = 0.3
        if g == 'adjective':
            value = 1.1 if word in PURPOSE else 0.7
        elif g == 'determiner':
            value = 0.5 if word in PURPOSE else 0.3
        if not boundary or g == 'verb':
            value = 0.0
    elif word in MARKET:
        value = 0.8 if g == 'adjective' else 0.4
        if previous in {'target', 'intended'}:
            value = 3.6
        if not boundary:
            value = 0.0
    elif word in {'case', 'cases'} and previous in USE:
        value = 3.0
    elif word in {'course', 'route'} and g == 'adjective':
        value = 0.65
    elif word in {'function', 'functions', 'role', 'roles'}:
        if previous in CENTRAL:
            value = 1.2
    elif word == 'of':
        if previous in USE:
            value = 0.8 * last + 0.5
        elif previous in APPLICATION:
            value = 2.7 if previous == 'applications' else 0.95
        elif previous in USER:
            value = 2.4
        elif previous in PURPOSE | SOURCE:
            value = 0.95 if previous in PURPOSE else 0.75
        elif previous in {'course', 'route', 'duties', 'units'}:
            value = 0.6
        elif previous in {'function', 'functions', 'role', 'roles'}:
            value = 0.35
    elif word == 'for':
        if previous in USE | PURPOSE:
            value = 0.9
        elif previous in MARKET:
            value = 2.0
        elif g == 'adjective':
            value = -0.08
    elif word in {'using', 'used'}:
        value = 0.2 if word == 'using' else 0.05
    elif word in {'uso', 'usos'}:
        value = 2.8 if boundary else 0.9
    elif word in {'用法', '用途'}:
        value = 1.5
    elif word in {'使用', '用', '利用'}:
        value = 0.4
    elif word in {'应用', '用户', '用戶', '原因', '市场', '受众', '听众'}:
        value = 1.0
    elif word == '法' and previous == '用':
        value = 2.7
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -2.35 if previous and set(previous) == {'·'} else 0.0
    return (doc, word, value), value

programs.haiku:
"""Words of use (v4). The component is a 'use and purpose' detector. It fires on the noun
'use' and its family (purpose, application, market, users, customers, sources, reasons),
on the 'of' that follows a noun of purpose ('the use of', 'the purpose of'), and on the
'for' that follows a noun of reason or fit ('reasons for', 'a substitute for'). It dips on
'for' after an adjective ('important for', 'liable for'). It is quiet on verbs: 'we use'
gives nothing. Positive values are the typical activation, in the same units."""
READS = ()

# Typical activation of each noun of use and purpose (singular, plural).
NOUNS = {
    "use": 1.3, "uses": 0.6, "usage": 1.2, "purpose": 0.9, "purposes": 0.6,
    "application": 0.5, "applications": 1.7, "market": 0.6, "markets": 0.6,
    "user": 0.3, "users": 0.9, "customer": 0.4, "customers": 0.3, "consumer": 0.5,
    "consumers": 0.3, "buyer": 0.3, "buyers": 0.6, "audience": 0.5,
    "reason": 0.4, "reasons": 0.8, "source": 0.4, "sources": 0.7,
    "abuse": 0.7, "misuse": 2.0,
}
# The same family in Chinese and Spanish or Italian.
FOREIGN = {"使用": 0.4, "用户": 1.3, "市场": 1.4, "应用": 1.4, "uso": 2.0}
# Nouns of function and purpose that take 'of' next: 'the use of', 'the purpose of'.
OF_NOUNS = {"use", "uses", "purpose", "purposes", "application", "applications", "source",
            "sources", "course", "abuse", "function", "functions", "role", "goal", "objective",
            "advantage", "importance", "nature", "origin", "target", "limitations"}
# Nouns of reason, basis or fit that take 'for' next: 'reasons for', 'a substitute for'.
FOR_NOUNS = {"reason", "reasons", "basis", "base", "substitute", "explanation", "use", "uses",
             "application", "applications", "market", "markets", "role", "candidate", "candidates",
             "name", "room", "time", "place", "opportunity", "opportunities", "fit", "replacement"}
# Adjectives that push 'for' down: 'notable for', 'important for', 'liable for'.
ADJ_FOR = {"notable", "famous", "important", "crucial", "essential", "good", "easy", "liable",
           "applicable", "effective", "appealing", "available", "suitable", "known", "key",
           "relevant", "valid", "named", "accessible", "useful", "favorable", "beneficial"}
# Words before a verb 'use' (subject pronouns, modals, 'to'): no activation.
VERB_BEFORE = {"we", "i", "you", "they", "can", "to", "would", "will", "must", "should",
               "could", "may", "people", "also"}
DEGENERATE = "··"  # a run of middle dots; the activation is about -2.35 throughout


def word(s):
    return s.strip(" -_\n\t").lower()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = word(prefix.token_strings[-2]) if same_doc else ""
    w = word(cur)
    v = 0.0
    if cur == DEGENERATE:
        v = -2.35
    elif w == "use" and prev in VERB_BEFORE:
        v = 0.0
    elif w in NOUNS:
        v = NOUNS[w]
    elif cur in FOREIGN:
        v = FOREIGN[cur]
    elif cur == " of" and prev in OF_NOUNS:
        v = 1.2
    elif cur == " for" and prev in FOR_NOUNS:
        v = 0.6
    elif cur == " for" and prev in ADJ_FOR:
        v = -0.8
    return carry, float(v)

programs.sol:
"""A local spelling response centered on 'still'.

The main response distinguishes capitalized/unspaced 'still' and its nearby
grammatical context.  Smaller rules cover stil/styl fragments, a few close
word spellings, and continuations after a piece ending in st.  In particular,
il(l) continues positively and r negatively.  Two separate responses are
modeled explicitly: Chinese 止 ('stop'), and the colon in initial 'Title:'.
The many irregular, token-specific multilingual echoes are not modeled.
"""
from anyascii import anyascii

READS = ()
COPULAS = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}
MODALS = {'can', 'could', 'may', 'might', 'must', 'will', 'would', 'should'}
PRONOUNS = {'i', 'we', 'you', 'he', 'she', 'it', 'they'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    text = anyascii(raw).lower().strip()
    if carry is None or carry[0] != doc:
        pos, previous, prev = 0, '', ''
    else:
        _, last_pos, previous, prev = carry
        pos = last_pos + 1
    state = (doc, pos, raw, text)
    value = 0.0

    if text == 'still':
        value = 5.45
        if raw.strip()[0].isupper() or not raw.startswith(' '):
            value = 7.4
        elif prev in COPULAS or prev in MODALS:
            value = 4.65
        elif prev in PRONOUNS:
            value = 4.85
        elif prev in {'and', 'while'}:
            value = 6.4
        elif prev in {'a', 'an', 'the'}:
            value = 7.0
        elif prev and not prev[-1].isalpha():
            value = 6.5
    elif raw == ':' and previous == 'Title' and pos == 1:
