"""layers.1.mlp.down_proj:4708 -- a "document-opening token" feature.

What it does: this component is silent everywhere except on the first token of a
document (the token right after <|endoftext|>, or the first token of a row). There its
activation is a fixed number that depends only on which token opens the document:
roughly positive for capitalised words and code-like identifiers (Along, Arc, Test,
ListNode, uint), near zero or slightly negative for function words, digits, punctuation
and special tokens. This program predicts that with four concept classes and group means.
It is a coarse approximation: the token-specific spread within each class is not captured.
"""

READS = ()

END_OF_TEXT = "<|endoftext|>"
FUNCTION_WORDS = set(
    "the a an of and to in is it that for on with as by at from or be this are was "
    "were he she they we you i his her its our their not but if so do does".split()
)
CODE_CHARS = set("{}();<>[]=\\_\t.")


def is_doc_start(prefix):
    """First token of the row, first token after a document-id change, or after <|endoftext|>."""
    if len(prefix.token_ids) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return True
    return prefix.token_strings[-2] == END_OF_TEXT


def token_class(text):
    word = text.strip()
    if text.startswith("<|") or "\n" in text or not word:
        return "low"
    if any("\u3040" <= c <= "\u9fff" or "\uac00" <= c <= "\ud7af" for c in word):
        return "cjk"
    if word.isdigit() or not any(c.isalnum() for c in word):
        return "low"
    if word.lower() in FUNCTION_WORDS:
        return "low"
    if any(c in CODE_CHARS for c in text) or any(a.islower() and b.isupper() for a, b in zip(word, word[1:])):
        return "code"
    if word[0].isupper() and word.isalpha() and text[0] != " ":
        return "cap"
    return "other"


MEAN_BY_CLASS = {"low": -0.24, "code": 1.38, "cap": 2.16, "other": 0.6, "cjk": -0.3}


def step(carry, prefix, upstream):
    if not is_doc_start(prefix):
        return carry, 0.0
    return carry, MEAN_BY_CLASS[token_class(prefix.token_strings[-1])]

