"""Blank lines and indentation-only lines: a sparse feature of line breaks (v6)."""
import re

READS = ()

# a line holding only indentation (spaces, tabs, a carriage return or a comment star), then its line break
BLANK_LINE = re.compile(r"[ \t\r]*\*?[ \t\r]*\n")


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""   # the previous token, within this document
    if cur != "\n" and BLANK_LINE.fullmatch(cur):
        if prev == "\n\n":
            return carry, 1.5            # blank-ish line after a blank line
        if BLANK_LINE.fullmatch(prev) and prev != "\n":
            return carry, (-1.2 if prev == " \n" else 0.3)   # blank-ish line after another one
        if prev.endswith("\n"):
            return carry, -2.0           # blank-ish line right after a line of code or text
        if prev.strip(" \t") == "":
            return carry, -0.8           # blank-ish line after a bare indent
        return carry, 0.0
    if cur == "import" and prev.endswith("\n\n"):
        return carry, 2.0                # 'import' opening a new block after a blank line
    if cur == "\r" and prev.endswith(("\n", "\r")):
        return carry, 1.3                # carriage return after a line break
    if cur == "··":
        return carry, -0.3               # dot leaders
    if cur.strip("\n") == "" and cur and prev.endswith("\n\n"):
        return carry, 4.8                # another line break in a run of blank lines
    return carry, 0.0

