Its activation is near zero at almost every token. Its large negative values come from a
handful of recognisable token types, so this program predicts it from the newest token and
the one or two tokens before it, with no state:

- a bare carriage return "\\r" (the kind left by Windows line endings or terminal progress
  output): strongly negative, most of all right after a newline (about -12), less after
  other text (about -1.5), and about -6 inside a run of carriage returns;
- the "{\\"" that opens a JSON tool call, after a tool-call tag or at the start of a line
  (about -2.2);
- a form feed, the page break in extracted PDF text (about -3.4);
- a dash rule "---" (about -1.5), a run of four or more separator characters such as
  "====" or "////" (about -0.8), and closing braces such as " }" or " }\\" (about -0.6 to -1.3);
- everything else: 0.
"""

READS = ()

SEPARATOR_CHARS = set("-=/^*#_~")
CLOSING_BRACES = {" }", "}", " },", "},", "}\\", " }\\", "··"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else "\n"
    recent = "".join(prefix.token_strings[-8:])
    if cur == "\r":
        if prev.endswith("\n"):
            return None, -12.0
        if prev == "\r":
            return None, -6.0
        return None, -1.5
    if cur == '{"' and ("tool" in recent or prev.endswith("\n")):
        return None, -2.2
    if cur == "\x0c":
        return None, -3.4
    if cur == "---":
        return None, -1.5
    if cur == " }\\":
        return None, -1.3
    if cur in CLOSING_BRACES:
        return None, -0.6
    if cur and set(cur) <= SEPARATOR_CHARS and len(cur) >= 4:
        return None, -0.8
    return None, 0.0

