import re
from anyascii import anyascii
import wordnet

READS = ()
TRANSFER = {'give', 'put', 'bring', 'take', 'send', 'pull', 'push', 'throw',
            'carry', 'hand', 'hold', 'turn', 'draw', 'yield', 'tug', 'change'}
MOTION = {'go', 'come', 'run', 'move', 'walk', 'step', 'fly', 'slip', 'sit'}
POSSESSIVE = {'my', 'your', 'his', 'her', 'its', 'our', 'their'}
OBJECTS = {'it', 'me', 'him', 'them', 'you', 'us', 'this'}
RETURNS = {'return', 'returns', 'returned', 'returning'}


