        return -9.1
    if bases & {'call'}:
        return -7.0
    if bases & TRANSFER:
        return -5.0
    if p in {'get', 'gets', 'getting'}:
        return -4.7
    if p in OBJECTS:
        return -3.8
    if bases & {'look', 'date'}:
        return -1.9
    if bases & MOTION:
