                     'at': -2.7, 'from': 2.1, 'of': 0.5, 'with': -0.6,
                     'over': -0.8, 'side': 3.5, '-side': 3.5,
                     'tracking': -4.7, 'drop': -3.2}.get(w, 0.0)
