            value = 0.29 if token.startswith(' ') else 0.49
        else:
            value = -0.35 if s in {')', ']', '}'} else 0.09
    elif s == '=>':
        value = -0.05
    elif word == 'be':
        value = -0.025
    elif s == '::':
        value = 0.06
    elif len(s) == 2:
        value = 0.007
    else:
        value = 0.004 if len(s) > 5 else 0.001

