import unicodedata
from anyascii import anyascii

READS = ()
FRENCH_OI_WORDS = {'moi', 'toi', 'soi', 'quoi', 'loi', 'roi'}
THAI_TONES = set('่้๊๋')


def alphabet(ch):
    name = unicodedata.name(ch, '')
    for family in ('LATIN', 'GREEK', 'CYRILLIC', 'HIRAGANA', 'KATAKANA', 'THAI'):
        if family in name:
            return family
    return ''


def response(token, previous, last, opening):
    word = token.strip()
    lower = word.lower()

    # Short oi pieces: not whole words such as 'point' or 'choice'.
    if lower == 'doi':
        if word.isupper():
            return -7.0
        return -8.5 if token[0].isspace() else -15.7
    if lower == 'joi':
        return -7.4
    if lower == 'oi' and last.lower() == 'u':
        return -0.5  # uoi is a different vowel sequence
    if lower == 'quoi' and previous.strip().lower() == 'pour':
        return 0.0  # the joined word is pourquoi, not standalone quoi
    if lower.endswith('oi') and len(word) <= 5:
        if word.isupper():
            return -5.0
        if lower == 'oi':
            return -4.2
        if lower in FRENCH_OI_WORDS:
            return -3.0
        return -3.8 if word.startswith('.') else -0.8
    if lower == 'ois':
        return -1.4
    if lower == 'lui':
        return -1.3
    if word == 'ii':
        return -0.4
    if ''.join(ch for ch in word if ch not in THAI_TONES) == 'อย':
        return -0.5

    # Read the spelling across a token boundary, not across a space.
    if last and token and not token[0].isspace():
        before, now = alphabet(last), alphabet(token[0])
        kana = {'HIRAGANA', 'KATAKANA'}
        if before and (before == now or {before, now} <= kana):
            left, right = anyascii(last).lower(), anyascii(token[0]).lower()
            if now == 'LATIN':  # preserve Latin diacritics
                left, right = last.lower(), token[0].lower()
            if left.endswith('o') and right == 'i':
                if now != 'LATIN':
                    return -0.8 if len(token) == 1 else 0.0
                if len(token) == 1:
                    return -6.5 if last == 'O' else -4.0
                if token.lower() == 'is':
                    return -4.5 if token[0].isupper() else -1.6
                return -0.2

    if previous.strip().lower() == 'doi':
        if token == ':':
            return -3.7 if previous.strip().isupper() else -7.0
        if token == '.org':
            return -5.5
    return 0.33 if opening and word.isalpha() else 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    opening = carry is None or carry[0] != document
    previous, tail = ('', b'') if opening else carry[1:]
    token = prefix.token_strings[-1]
    # Joining bytes recovers a preceding character split by the tokenizer.
    last = tail.decode('utf-8', errors='ignore')[-1:]
    value = response(token, previous, last, opening)
    tail = (tail + prefix.token_bytes[-1])[-24:]
    return (document, token, tail), value

