    raw = prefix.token_bytes[-1]
    decoder = codecs.getincrementaldecoder("utf-8")("replace")
    text = decoder.decode(pending + raw, final=False)
    pending = decoder.getstate()[0]
    word = text.strip()
    value = 0.0
    if first:
        if raw.startswith(b"<|"):
            value = -0.43
        elif not word or text.isspace():
            value = -0.22
        elif "\ufffd" in text:
            value = -0.23
        elif word.isdecimal():
            value = -0.19
        elif word.isascii() and word.isalpha():
            value = -0.04 if word.islower() else -0.11
        else:
            value = -0.16

    if word in {"驾", "駕"}:
        value = -0.9 if tail.endswith("代") else -3.0
    elif word in {"驾驶", "駕駛", "驾车", "駕車"}:
        value = -0.5
    elif word in RIDE:
        value = -0.5
    elif word in DRIVE:
        value = -0.25
    elif word in {"驴", "驢", "鞍"}:
        value = -0.8
    elif word == "鞭":
        value = -1.4
    elif word == "架":  # frame; 高架 means an elevated structure
        value = -3.2 if tail.endswith("高") else -0.3
    elif word in HEAD_COVER:
        value = -0.5
    elif word == "刮":  # scrape or shave
        value = -0.7
    elif word in {"平均", "平均每"}:  # average; average per
        value = -0.4 if word == "平均" else -1.4
    elif word in {"浏", "瀏"}:  # first character of "browse"
        value = 2.0
    elif word in {"驳", "駁"}:  # refute/reject
        value = 1.0 if word == "驳" else 2.2
    elif word == "回" and tail.endswith(("驳", "駁")):  # reject an appeal
        value = 2.9
    elif word in {"果", "结果", "結果"}:  # fruit/result
        value = 0.15
    elif word == "支持":  # support
        value = 0.3
    elif word.lower() in CONTRAST:
        value = 0.08
    elif word.lower() in TOTALITY:
        value = -0.07
    elif word == "··":
        value = -1.27
    elif raw == b"\x00":
        value = -1.9 if first else 0.13
    elif first and raw == b"\\n":
        value = -1.41
    elif first and raw == b"//\n":
        value = -2.5
    elif word == "^^^^" and initial_carets:
        value = -1.6

    initial_carets = initial_carets and bool(text) and set(text) == {"^"}
    return (doc, pending, (tail + text)[-16:], initial_carets), value

programs.haiku:
"""Draft 3: a few named triggers, with the document start treated separately.

Triggers, each a concept rather than a learned table:
- the filler token "··" (a run of middle dots): strongly negative;
- 驾, the drive character (驾驶, 凌驾, 三驾马车), strongly negative, and other
  riding, driving, climbing and wearing verbs (骑 驶 乘 爬 架 戴), mildly negative;
- the first token of a document (no preceding context): mildly negative,
  and the chat-template marker <|im_start|> there is more negative.
"""
READS = ()

DOT_LEADER = "··"
DRIVE = "驾"
RIDE_OR_WEAR = {"骑", "驶", "乘", "爬", "架", "戴"}
CHAT_MARK = "<|im_start|>"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    t = prefix.position
    doc_start = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if tok == DOT_LEADER:
        value = -1.27
    elif tok == DRIVE:
        value = -3.6
    elif tok in RIDE_OR_WEAR:
        value = -0.45
    elif doc_start and tok == CHAT_MARK:
        value = -0.44
    elif doc_start:
        value = -0.1
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Mainly a small trailing-digit detector, strongest on 12 and 30/31.

Digit identity, the preceding digit's parity, and place within a digit
run determine the response. Decimal points weaken it; a document-initial
12 is unusually strong. Spelled-out 11, 12 and 30, November/December,
and short/shortly receive positive responses. Other month names are
slightly negative (May is neutral). Doubled backslashes are positive;
a space-prefixed pair after the TeX command hfill is negative. Other
text is predicted near zero, omitting many small contextual effects.
"""
import calendar
import inflect
import re

READS = ()
MONTHS = {name: n for n, name in enumerate(calendar.month_name) if name}
# Ordinary and ordinal spellings of the same small numbers.
_inflect = inflect.engine()
NUMBER_WORDS = {}
for number, response in ((11, 0.4), (12, 1.0), (30, 0.5)):
    NUMBER_WORDS[_inflect.number_to_words(number)] = response
    NUMBER_WORDS[_inflect.number_to_words(_inflect.ordinal(number))] = response


def digit_response(previous, current, second):
    if current == '2':
        if previous == '1':
            return 1.08 if second else 0.67
        if previous in '3579':
            return 0.68
        if previous == '4':
            return 0.15
        if previous == '2':
            return -0.11
    if current == '1':
        if previous == '3':
            return 0.91 if second else 0.35
        if previous in '12':
            return 0.48 if second else 0.13
        return 0.12 if second and previous != '0' else 0.0
    if current == '0' and previous == '3':
        return 1.05 if second else 0.48
    # Several weaker digit responses also separate odd and even predecessors.
    odd = int(previous) % 2 == 1
    if current == '6':
        return -0.13 if not odd else 0.08 if previous != '1' else 0.0
    if current in '78' and odd:
        return -0.09
    if current == '4' and odd:
        return -0.06
    if current == '0' and previous in '148':
        return -0.13 if previous == '4' else -0.06
    return -0.03


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', '', 0, 0, '')
    _, previous, before_previous, run_length, age, word = carry
    text = prefix.token_strings[-1]
    digit = len(text) == 1 and text in '0123456789'
    value = -0.002
    if digit:
        if run_length:
            value = digit_response(previous, text, run_length == 1)
            if run_length == 1 and before_previous == '.':
                value *= 0.75
            if run_length == 1 and previous == '3' and text == '0':
                if before_previous in (':', '/'):
                    value += 0.25
            if age == 1 and previous == '1' and text == '2':
                value = 4.69
        elif (previous == '.' and before_previous
              and before_previous in '0123456789'):
            value = 0.4 * digit_response(before_previous, text, True)
        elif age == 0:
            value = 1.10 if text == '0' else -0.22
        else:
            value = -0.025
    # Two backslashes are an escaped backslash or a typesetting line break.
    if text.endswith('\\\\'):
        value = -1.1 if text.startswith(' ') and word == 'hfill' else 0.5

    if not text or not text[0].isalpha():
        word = ''
    match = re.search(r'[A-Za-z]+$', word + text)
    word = match.group()[-24:] if match else ''
    if word.lower() in NUMBER_WORDS:
        value = NUMBER_WORDS[word.lower()]
    elif word in MONTHS:
        month = MONTHS[word]
        value = 0.54 if month == 12 else 0.26 if month == 11 else -0.13
        if month == 5:  # "May" also has a common non-calendar use.
            value = 0.0
    elif word.lower() == 'short':
        value = 0.22
    elif word.lower() == 'shortly':
        value = 1.05

    return (document, text, previous, run_length + 1 if digit else 0,
            age + 1, word), value

"""Sparse signals for recognizable word fragments and text layout.

Track the current word, ignoring NUL separators and soft hyphens. A short
upper-case piece, or a piece after damaged typography, is more likely to
respond when the repaired spelling belongs to a common English word.
A few recurring labels and chat delimiters are calibrated separately.
Unrecognized positions are usually zero; this is only a partial account
of the component's diverse lexical responses.
"""
import re
import unicodedata
from wordfreq import top_n_list

READS = ()
WORDS = set(top_n_list('en', 30000))
WORD_PREFIXES = {
    w[:i] for w in WORDS if w.isalpha()
    for i in range(3, min(len(w), 20))
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, word, only_cr = 0, '', '', True
    else:
        _, position, previous, word, only_cr = carry
    token = prefix.token_strings[-1]
    before = word
    clean = token.replace('\x00', '').replace('\xad', '')
    if clean.isalpha():
        word += clean
    elif clean:
        m = re.search(r'[^\W\d_]+$', clean)
        word = m[0] if m else ''
    spelling = unicodedata.normalize('NFKC', word).lower()
    familiar = spelling in WORDS or spelling in WORD_PREFIXES

    value = -0.11 if position == 0 else 0.0
    if token == '\r':
        value = -1.28 if only_cr else -0.10
    elif token and set(token) == {'·'} and previous and set(previous) == {'·'}:
        value = 0.26
    elif token.isalpha() and previous:
        if '\x00' in previous:
            length = len(spelling)
            value = (0.05 if length == 1 else 0.15 if length == 2
                     else 0.35 if length == 3 else 0.50 if length <= 7
                     else 0.30)
        elif '\xad' in previous:
            value = 0.65 if familiar and len(spelling) >= 4 else 0.10
        elif any(ch in previous for ch in 'ﬀﬁﬂﬃﬄ'):
            if familiar and len(spelling) >= 4:
                value = 0.50
        elif (token.isupper() and before.isupper() and len(token) <= 3
              and len(word) >= 6 and spelling in WORD_PREFIXES
              and spelling not in WORDS):
            value = 0.25

    if token.isalpha() and word == 'OBSERV':
        value = 0.74
    elif word == 'OBSERVATION' and token == 'ATION':
        value = 0.10
    elif token.isalpha() and word.lower() == 'deprec':
        value = 0.78
    elif word.lower() == 'deprecation' and token.lower() == 'ation':
        value = 0.30
    elif position == 1 and previous == 'Title' and token == ':':
        value = 4.34
    elif previous.strip() in ('|', ':') and token == ' member':
        value = 0.35
    elif token == '<tool_response>':
        value = -0.10
    elif token == '</tool_call>':
        value = -0.08
    elif previous == '<|im_start|>' and token == 'user':
        value = 0.09
    elif previous == 'assistant' and token == '\n':
        value = 0.05

    return (doc, position + 1, token, word[-40:],
            only_cr and token == '\r'), value

programs.haiku:
"""Possessive-'s detector: the component is strongly negative on the possessive ending
"'s" / "’s" after a proper name (Faraday's, Liza Minnelli's), most strongly when the name
follows a preposition ("of Faraday's" style), weakly negative after a common noun (the
men's), weakly positive on contractions after a pronoun or "let" (It's, let's, there's),
and zero elsewhere.
"""

READS = ()

POSSESSIVE = {"'s", "’s", "'S", "’S"}
APOSTROPHE = {"'", "’"}
CONTRACTION_HOSTS = {"it", "that", "he", "she", "let", "there", "here", "what", "who", "where", "this"}
PREPOSITIONS = {"of", "with", "to", "from", "in", "by", "and", "for", "at", "on"}


def _word_start(prefix):
    """Index of the first subword token of the word just before the last token."""
    toks = prefix.token_strings
    docs = prefix.document_ids
    j = len(toks) - 2
    while j > 0 and not toks[j].startswith((" ", "\n")) and docs[j - 1] == docs[-1]:
        j -= 1
    return j


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return carry, 0.0
    if toks[-1] not in POSSESSIVE and toks[-1] not in APOSTROPHE:
        return carry, 0.0
    j = _word_start(prefix)
    word = "".join(toks[j:-1]).strip(" \n\"“”‘’'(")
    if word.lower() in CONTRACTION_HOSTS:
        return carry, 0.3
    if toks[-1] in APOSTROPHE:
        return carry, -0.4 if word[:1].isupper() else 0.0
    if word[:1].isupper() or word[:1].isdigit():
        before = toks[j - 1].strip() if j > 0 else ""
        return carry, -4.5 if before in PREPOSITIONS else -2.5
    return carry, -0.4
